export const DE: Record<string, string> = {
  "monet-stacks-wheat": "Eine von über fünfundzwanzig Leinwänden, die Monet zwischen dem Sommer 1890 und 1891 von den Getreideschobern auf den Feldern neben seinem Haus in Giverny malte. Es war seine erste echte Serie — dasselbe Motiv über Jahreszeiten und Tageszeiten hinweg wiederholt —, und als 1891 fünfzehn davon bei Durand-Ruel in Paris gezeigt wurden, waren sie binnen Tagen verkauft. Das Bild handelt davon, wie Licht die Farbe verändert: Ein einziger Schober trägt Rosa, Orange und Violett.",
  "monet-water-lilies": "Eine frühe Leinwand aus der Serie der Seerosen, gemalt an dem Teich, den Monet in seinem Garten in Giverny anlegte. Um 1906 schnitt er Ufer und Himmel aus dem Bildausschnitt heraus und behielt nur die Wasseroberfläche, sodass Seerosenblätter, Blüten und gespiegelte Wolken in einer Ebene liegen. Weil es kaum Hinweise auf oben und unten gibt, ist es ein anspruchsvolles Puzzle — die rosa Blüten sind aber gute Orientierungspunkte.",
  "monet-arrival-normandy-train": "1877 stellte Monet seine Staffelei im Pariser Bahnhof Saint-Lazare auf und malte zwölf Ansichten von Zügen und Dampf. Dies ist eine davon; sie hält den Moment fest, in dem sich der Rauch der Lokomotive wie blauer Nebel unter dem Glasdach ausbreitet. Ein Schlüsselbeispiel dafür, wie die Impressionisten nicht nur die Natur, sondern auch die Maschinen und das Tempo der modernen Stadt zum Thema machten.",
  "monet-beach-sainte-adresse": "Gemalt, als Monet sechsundzwanzig war, in Sainte-Adresse, dem Küstendorf bei seiner Heimatstadt Le Havre. Auf den Sand gezogene Fischerboote, ein grauer Himmel und weiße Brandung sind in dicken Strichen hingesetzt. Er war damals mittellos und lebte bei seinem Vater; ein paar Jahre später sollte aus dem Licht dieser Küste Impression, Sonnenaufgang werden.",
  "monet-cliff-walk-pourville": "Zwei Frauen mit Sonnenschirmen blicken 1882 von den Klippen bei Pourville in der Normandie aufs Meer hinaus. Monet malte das Gras in kurzen, vom Wind gebogenen Strichen und zerlegte die See in Tupfer vieler Farben. Die Frauen sind vermutlich Töchter von Alice Hoschedé, die er im folgenden Jahr heiratete.",
  "monet-water-lily-pond": "Die japanisch anmutende Bogenbrücke in Monets Garten in Giverny, gemalt 1900. 1893 kaufte er das Grundstück, ließ den Teich ausheben und die Brücke bauen; mit dieser Brückenserie beginnen seine Gartenbilder. Weidenzweige, der Bogen der Brücke und die Seerosenblätter schichten sich in drei Lagen — von oben nach unten zu arbeiten ist hier der bequeme Weg.",
  "monet-bordighera": "1884 verbrachte Monet drei Monate in Bordighera an der italienischen Riviera und war vom Licht des Mittelmeers überwältigt. Hier erscheinen Stadt und Meer zwischen knorrigen Pinien und Palmen; er schrieb, für dieses Licht bräuchte man „eine Palette aus Diamanten und Edelsteinen“. Blau- und Rosatöne reichen bis in die Schatten hinein.",
  "monet-stacks-wheat-2": "Aus derselben Schoberserie: eine Leinwand vom Herbstabend bei Sonnenuntergang. Die beschattete Seite des Schobers ist blau und violett, während die besonnte Kante orange und rot glüht. Monet arbeitete an mehreren Leinwänden gleichzeitig und wechselte, sobald sich das Licht änderte; seine Stieftochter Blanche karrte sie auf einer Schubkarre hinaus.",
  "monet-bank-seine": "Im Sommer 1868 setzte der siebenundzwanzigjährige Monet seine Gefährtin Camille in den Schatten eines Baumes am Seineufer. Das Dorf am anderen Ufer hängt kopfüber im Wasser, und Blattschatten sprenkeln ihr weißes Kleid. Das Bild gilt oft als ein Ausgangspunkt des Impressionismus: Licht und Spiegelung, direkt im Freien beobachtet.",
  "cezanne-basket-apples": "Das berühmteste von Cézannes Stillleben. Der gekippte Korb, die nicht zueinander passenden Tischkanten und die gestapelten Kekse sind keine Fehler, sondern mehrere Blickpunkte auf einer Fläche vereint — ein Gedanke, den Picasso in den Kubismus weitertrug. Cézanne arbeitete wochenlang an einem Arrangement, bis die Äpfel faulten.",
  "cezanne-bay-marseille": "Cézanne malte diesen Blick über die Bucht von Marseille von L'Estaque aus, dem Fischerdorf, in dem seine Mutter ein Haus hatte. Orangefarbene Dächer, tiefblaues Meer und fliederfarbene Hügel schichten sich in waagerechten Bändern, hingesetzt in ziegelartigen Strichen. An Pissarro schrieb er, das Meer sehe hier aus „wie eine Spielkarte vor schwarzen Silhouetten“.",
  "cezanne-madame-cezanne": "Cézanne malte seine Frau Hortense Fiquet mehr als neunundzwanzigmal; dies gehört zu einer Gruppe im roten Kleid auf gelbem Sessel. Ihr starrer Ausdruck rührt von stundenlangen Sitzungen her, bei denen er ihr angeblich sagte, sie solle stillhalten „wie ein Apfel“. Das Rot des Kleides und das Gelb des Sessels drängen gegeneinander.",
  "cezanne-auvers": "Gemalt um 1873, als Cézanne in Auvers-sur-Oise lebte und von seinem Nachbarn Pissarro lernte. Dächer und Felder fügen sich wie Flickwerk zusammen, und der Pinselstrich ist noch weich, nah am Impressionismus. Van Gogh sollte dasselbe Dorf siebzehn Jahre später malen; er liegt dort begraben.",
  "cezanne-vase-tulips": "Rote Tulpen und weiße Blüten in einem grünen Steingutkrug, davor ein paar Äpfel. Cézanne verwendete mitunter Papierblumen, weil echte welkten, bevor er fertig wurde — vielleicht wirken diese Blütenblätter deshalb so knackig. Die graublaue Wand dahinter schiebt die roten Blüten nach vorn.",
  "cezanne-plate-apples": "Ein Stillleben um 1877: ein Teller Äpfel vor blauer Blümchentapete. Cézanne sagte, er wolle „Paris mit einem Apfel erobern“, und malte in seinem Leben Hunderte davon. Jeder Apfel ist mit Farbbändern modelliert, die von Rot nach Grün drehen — die Teile findet man über die Richtung des Farbverlaufs.",
  "pissarro-place-du-havre": "1893, mit dreiundsechzig, machte ein Augenleiden Pissarro das Arbeiten im Freien schwer, also malte er die Straße aus einem Pariser Hotelfenster. Kutschen und Passanten auf dem Platz vor dem Bahnhof Saint-Lazare und die Haussmann-Fassaden sind von hoch oben gesehen. Das Bild stammt aus dem ersten Jahr seiner Stadtserie.",
  "pissarro-crystal-palace": "Pissarro floh 1870 vor dem Deutsch-Französischen Krieg nach London und malte dies im Jahr darauf in Sydenham im Süden der Stadt. Der Glasbau rechts ist der Crystal Palace der Weltausstellung von 1851, 1936 durch Feuer zerstört — was das Bild zu einem seltenen Zeugnis macht. Spaziergänger, eine Kutsche und ein Winterhimmel sind still hingesetzt.",
  "pissarro-woman-child-well": "Eine Frau und ein Kind unterhalten sich am Brunnen eines Bauernhofs in Pontoise, gemalt 1882. In diesen Jahren konzentrierte sich Pissarro auf Figuren und malte das Landleben in großem Format mit kleinen, gleichmäßigen Strichen, die die ganze Fläche füllen. Die blaue Schürze und die grüne Wand führen durch die Teile.",
  "pissarro-rabbit-warren-pontoise": "Ein verschneites Dorf am Hang von Pontoise im Winter 1879. Der Schnee ist nicht weiß gemalt, sondern blau, rosa und grau, mit kahlen Bäumen, die dunkle Linien hineinziehen. Pissarro arbeitete damals neben Cézanne und Gauguin, und der dichte Pinselstrich zeigt diesen Austausch.",
  "pissarro-haymaking-eragny": "Landarbeiterinnen wenden Heu auf den Wiesen von Éragny, wo Pissarro seine letzten Jahre verbrachte. 1892 gemalt, kurz nach seinem Ausflug in den Pointillismus, behält das Bild kleine Tupfer und leuchtende Farbe. Die blaue Kleidung und die weißen Kopftücher der Frauen sprenkeln das grüne Feld — die Figuren zuerst zu suchen, verankert das Brett.",
  "pissarro-snow-louveciennes": "Eine verschneite Straße in Louveciennes, dem Dorf westlich von Paris, in dem Pissarro um 1870 lebte. Bald darauf besetzten preußische Truppen das Haus, und über tausend zurückgelassene Gemälde gingen verloren; dies ist eines der wenigen erhaltenen. Zwei Gestalten im Schnee sind die einzigen Farbflecken unter dem grauen Himmel.",
  "sisley-turn-road": "Eine Biegung einer Dorfstraße bei Paris, 1873 von Sisley gemalt. Von allen Impressionisten war er derjenige, der am beharrlichsten Landschaft malte, und er behandelte den Himmel als Hauptfigur — oft gab er ihm mehr als die halbe Leinwand. Auch hier ist der bewölkte Himmel weit, und die gelbe Mauer entlang der Straße hält einen auf Kurs.",
  "sisley-seine-port": "Am Seineufer bei Marly, wo Sisley 1875 lebte, wird Sand entladen, daneben liegen Lastkähne. Der im Fluss gespiegelte Himmel, weißer Sand und graue Boote verlaufen waagerecht über einem niedrigen Horizont. Im Jahr darauf trat der Fluss schwer über die Ufer, und auch das malte Sisley — als Serie.",
  "sisley-street-moret": "Eine Straße in Moret-sur-Loing, der Stadt am Wald von Fontainebleau, in der Sisley seine letzten zwanzig Jahre verbrachte. Um 1890 gemalt, glühen die Mauern der Gasse im schrägen Licht rosa und cremefarben, am Ende steht der Kirchturm. Er starb dort in Armut; seine Preise stiegen erst nach seinem Tod.",
  "sisley-watering-place-marly": "Der Teich von Marly, an dem zu Zeiten Ludwigs XIV. die königlichen Pferde tranken, gemalt 1875. Das Schloss war längst verschwunden, doch Teich und Bäume blieben als Ort zum Spazieren für die Dorfbewohner. Bäume und weiße Wolken spiegeln sich im Wasser und machen die obere und die untere Bildhälfte beinahe symmetrisch.",
  "sisley-landscape-along-seine": "Ein Blick die Seine entlang mitten in Paris, auf den Pont des Arts und die Kuppel des Institut de France, gemalt um 1875. Sisley malte selten das Zentrum von Paris, was dieses Bild ungewöhnlich macht. Fluss, Brückengeländer und Kuppel schichten sich als Waagerechte unter einem weiten, offenen Himmel.",
  "corot-view-genoa": "Eine Ölskizze auf Papier von Corots zweiter Italienreise 1834, mit Blick von einem Hügel hinab auf den Hafen von Genua. Der junge Corot machte Hunderte solcher Freilichtstudien; ihr klares Licht und ihre einfachen Flächen sind der Grund, warum die Impressionisten ihn später eine Vaterfigur nannten. Dächer, Meer und Himmel legen sich zu drei Farbfeldern.",
  "corot-monte-pincio": "Die Promenade auf dem Pincio mit Blick über Rom, von Corot in den 1840er Jahren gemalt. Silbriger Himmel, blasses Grün und erdfarbene Gebäude ergeben jene weiche Tonigkeit, die seine Handschrift ist. Die in Italien entstandenen Skizzen bewahrte er in seinem Pariser Atelier auf und kam sein Leben lang darauf zurück.",
  "constable-stoke": "Die Kirche von Stoke-by-Nayland in Constables Heimat Suffolk, 1836 auf ihrem Hügel. Diese paar Meilen Landschaft malte er sein Leben lang und sagte, sie habe ihn „zum Maler gemacht“. Mit dem Messer aufgesetzte weiße Tupfer und schwere Wolken sind ein englischer Himmel, wie er ist.",
  "turner-fishing-boats-hucksters": "Ein Seestück Turners von etwa 1837: Händler feilschen mit Fischern um den Fang, mitten in den Wellen treibend. Boote und Menschen sind kaum mehr als Formen, während Gischt und Licht die Szene verschlucken. Kritiker der Zeit spotteten über solche Bilder als „Seifenlauge und Tünche“; heute liest man sie als Vorahnung der Abstraktion.",
  "gogh-bedroom": "Die zweite von drei Fassungen von van Goghs Schlafzimmer im Gelben Haus in Arles, 1889 in der Heilanstalt von Saint-Rémy nach der ersten wiederholt. Seinem Bruder Theo schrieb er, allein die Farbe solle „Ruhe oder Schlaf im Allgemeinen“ ausdrücken. Fliederfarbene Wände, roter Ziegelboden und butterfarbenes Bett zerfallen in einfache Zonen, sodass die Teilegrenzen klar sind.",
  "gogh-self-portrait": "Eines von über dreißig Selbstbildnissen, die van Gogh in Paris malte — vor dem Spiegel, weil er sich keine Modelle leisten konnte. Er hatte gerade Seurats Pointillismus aufgenommen und baute Gesicht und Hintergrund aus kurzen Punkten und Strichen. Komplementärpaare, Grün zu Rot und Blau zu Orange, stoßen Punkt für Punkt aneinander und scheinen aus der Ferne zu flirren.",
  "gogh-poets-garden": "Der öffentliche Garten gegenüber dem Gelben Haus in Arles, 1888 gemalt. Van Gogh stellte sich vor, der mittelalterliche Dichter Petrarca sei hier spazieren gegangen, nannte ihn „Garten des Dichters“ und malte eine Serie für das Zimmer, das er für Gauguin herrichtete. Runde Sträucher, gelber Rasen und blauer Himmel teilen sich in breite Flächen.",
  "gogh-fishing-spring": "Angler an der Brücke von Asnières an der Seine, gemalt im Frühjahr 1887 während van Goghs Pariser Jahren. Er zog damals mit Signac in die Vorstädte hinaus, um helle Farbe und kurze Striche zu erproben. Wasser und junges Laub sind pastellhell — ein van Gogh, der den dunklen holländischen Jahren gar nicht ähnelt.",
  "gogh-madame-roulin-rocking": "Augustine Roulin, die Frau des Postboten von Arles, hält die Schnur einer Wiege; van Gogh malte das Motiv fünfmal. Er dachte es sich in einer Schiffskajüte hängend, damit Seeleute an die Wiegenlieder ihrer Kindheit denken. Grünes Kleid, roter Boden und Blumentapete treffen als kräftige Farbfelder aufeinander, sodass jedes Teil klar irgendwohin gehört.",
  "gogh-terrace-observation-deck": "Die Aussichtsterrasse neben der Mühle auf dem Montmartre, wo van Gogh wohnte, gemalt Anfang 1887. Laternen, Geländer und Menschen, die über Paris blicken, stehen unter einem grauen Winterhimmel. Wegen der stillen Töne, kurz vor seiner Wendung zur hellen Farbe, sagen viele, es sehe nicht nach van Gogh aus.",
  "gogh-grapes": "Ein Früchtestillleben vom Herbst 1887 in Paris: gelbe Früchte auf gelbem Grund, ein Versuch darüber, wie viele Töne eine einzige Farbe fassen kann. Die Striche wirbeln wie Wasser um die Früchte, und die violetten Trauben sind der eine komplementäre Ton, der alles verankert. Die gelben Stillleben jenes Jahres führen zu den Sonnenblumen von Arles.",
  "gauguin-arlesiennes": "Gemalt in den zwei Monaten, die Gauguin 1888 mit van Gogh in Arles verbrachte. Frauen verbergen ihre Gesichter in Tüchern vor dem kalten Mistral, während sie denselben Park durchqueren, den van Gogh den Garten des Dichters nannte. Gauguin schneidet die Formen in flache, von Konturen begrenzte Farbe — das Gegenteil von van Goghs Wirbeln.",
  "gauguin-merahi-metua-tehamana": "Tehamana, das dreizehnjährige Mädchen, das während Gauguins erstem Tahiti-Aufenthalt bei ihm lebte, im Missionskleid, gemalt 1893. Die Osterinsel-Zeichen und der Götze an der Wand dahinter sind die „Ahnen“ des Titels, von Gauguin erfunden. Gelbe Wand, weiße Blüten und violettes Kleid teilen sich in einfache Flächen.",
  "gauguin-mahana-atua": "1894 in Paris gemalt, zwischen Gauguins beiden Tahiti-Aufenthalten, aus Erinnerung und Vorstellung. Der Götze in der Mitte ist kein echter tahitianischer Gott, sondern Gauguins eigene Mischung aus mehreren Kulturen, und der Teich unten löst sich in abstrakte Lachen aus Rosa, Gelb und Blau auf. Ein Markstein der symbolistischen Malerei; das untere Band ist reine Abstraktion.",
  "gauguin-te-aha-oe": "Frauen vor Dorfhütten während Gauguins zweitem Tahiti-Aufenthalt 1896; der Titel ist tahitianisch. Statt einer wirklichen Szene ordnete er Figuren aus Jahre zuvor entstandenen Bildern zu dieser Komposition um. Rote Erde, grünes Gras und weiße Hühner liegen in breiten Farbzonen.",
  "gauguin-polynesian-woman-children": "Aus Gauguins letzter Tahiti-Zeit 1901, kurz bevor er zu den Marquesas aufbrach. Eine Frau in Blau hält ein Kind auf dem Arm, ein weiteres steht daneben — eine Komposition wie eine Madonna —, und ein weißer Hund sitzt dabei. Obwohl er krank und verschuldet war, ist die Farbe ruhig und warm.",
  "gauguin-te-raau-rahi": "Eine Hütte und Dorfbewohner unter einem großen Baum, gemalt 1891, in Gauguins erstem Jahr auf Tahiti. Die europäische Perspektive klingt noch nach, doch der rote Pfad und das grüne Laub flachen bereits zu Farbfeldern ab. Er war auf der Suche nach dem Paradies gekommen; das Dorf war längst französische Kolonie.",
  "caillebotte-paris-street-rainy": "Caillebottes Hauptwerk, gezeigt auf der Impressionistenausstellung von 1877: eine Kreuzung an einem der neuen Boulevards des Baron Haussmann an einem Regentag. Das Paar mit Schirm scheint gleich aus dem Bild zu treten, und die fotografische Perspektive war für ihre Zeit radikal. Weites nasses Pflaster und graue Fassaden machen es zu einer guten Wahl für viele Teile.",
  "church-view-cotopaxi": "Der Anden-Vulkan Cotopaxi, gemalt vom Amerikaner Church aus der Hudson River School nach seiner Ecuadorreise von 1853. Er hatte den Naturforscher Humboldt gelesen und war ihm nach Südamerika gefolgt. Palmen und ein Wasserfall im Vordergrund führen in dramatischer Perspektive zum schneebedeckten Kegel.",
  "inness-home-heron": "Ein abendliches Marschland, 1893 von Inness in späten Jahren gemalt: Bäume im Dunst, ein gerötetter Himmel und ein einzelner Reiher. Vertieft in die Mystik Swedenborgs, suchte er Stimmung und Geist statt genauer Beschreibung. Die weichen Ränder machen es schwer, doch Wärme und Kühle der Farbe trennen die Bereiche.",
  "inness-early-morning": "Morgen in Tarpon Springs, Florida, wo Inness seine Winter verbrachte, gemalt 1892. Ein rotes Dach und eine kleine Gestalt stehen auf einem nebligen Feld, während der Himmel von Rosa nach Blau ausblutet. Dieses dunstige Leuchten baute er auf, indem er dünne Farbschichten über die Untermalung lasierte.",
  "inness-after-summer-shower": "1894 gemalt, wenige Monate vor Inness' Tod. Nach einem Schauer spannt sich ein Regenbogen über die nasse Wiese, und Licht bricht durch die Wolken. Die Formen haben sich fast aufgelöst, doch das helle Himmelsband und die dunklen Baummassen geben den Teilen ihre Richtung.",
  "inness-catskill-mountains": "Das weite Tal der Catskill Mountains nördlich von New York, gemalt 1870. Inness folgte damals noch der detaillierten Art der Hudson River School, sodass jeder Baum und jede Wolke deutlich bleibt. Eine kleine rote Gestalt und ein weißes Haus führen durch die grüne Weite.",
  "inness-old-mill": "Ein Frühwerk von 1849, als Inness vierundzwanzig war: eine alte Mühle am Bach, Vieh davor. Die Braun- und Grüntöne gehören zur überlieferten Landschaftsmalerei, doch die hellen Wolken zeigen schon sein Interesse am Licht. Die Spiegelung der Mühle im Wasser ist der Hinweis für die unteren Teile.",
  "daubigny-marsh": "Ein abendliches Marschland, 1871 von Daubigny aus der Schule von Barbizon gemalt, mit einem Wolkenhimmel, der über einem niedrigen Horizont fast die ganze Leinwand füllt. Er malte von einem zum schwimmenden Atelier umgebauten Boot aus und ermutigte den jungen Monet zur Arbeit im Freien. Der in den Tümpeln gespiegelte Himmel schneidet Wege durch den dunklen Grund.",
  "fantin-latour-still-life": "Ein Stillleben von 1873: eine Vase, Früchte und ein Glas auf weißem Tuch. Es ist das Gegenstück zu Fantin-Latours Gruppenbildnis Um den Tisch, auf dem die Dichter Rimbaud und Verlaine zu sehen sind — als wären die Menschen gegangen und nur die Dinge geblieben. Dunkler Grund und weißes Tuch setzen einen scharfen Kontrast.",
  "fantin-latour-still-life-flowers": "Fantin-Latour lebte von Blumenbildern, die vor allem englische Sammler schätzten. Auf dieser Leinwand von 1881 steht ein Arm voll Sommerblumen vor dunklem Grund, sodass jedes Blütenblatt seine Farbe behält. Die Lage der weißen und roten Blüten dient als Karte für die Teile.",
  "fantin-latour-roses-bowl": "Ein paar rosa und weiße Rosen in einer flachen Schale, gemalt 1881. Fantin-Latour malte gern die Rosen, die seine Frau Victoria zog, und man sagte, seine Rosen dufteten. Entscheidend sind die feinen Rosaverschiebungen in den Blättern — ein Puzzle zum Hineinzoomen.",
  "chardin-white-tablecloth": "Ein Stillleben um 1731 des französischen Malers Chardin: Brot, eine Flasche, Wurst und ein Messer auf weißem Tuch. In einer Zeit großer Hofmalerei bewunderte man ihn dafür, dass er schlichte Küchendinge redlich malte. Die glatte Oberfläche zeigt kaum Pinselspuren, sodass viele Teile allein über die Form zusammenfinden.",
  "manet-fish": "Ein Stillleben von 1864: Karpfen, Aal, eine Rotbarbe, Austern und eine Zitrone auf weißem Tuch. Nach dem Skandal um die Olympia wandte sich Manet kurz dem Stillleben zu und übernahm den Aufbau der holländischen Malerei des 17. Jahrhunderts, aber mit schnellem, kühnem Pinsel. Silbrige Schuppen und eine Kupferpfanne sind die Teile, die aufblitzen.",
  "manet-woman-reading": "Eine Frau liest eine Zeitschrift in einem Pariser Café, gemalt um 1880 in Manets letzten Jahren. Krankheit machte große Formate schwer, also malte er kleine Cafészenen wie diese mit raschen Strichen; das Grün hinter ihr ist das Laub des Cafégartens. Der schwarze Hut und die weiße Seite sind klare Ankerpunkte im Grün.",
  "manet-bullfight": "Gemalt, nachdem Manet 1865 auf seiner Spanienreise einen Stierkampf gesehen hatte. Er schrieb von dessen „glänzendem Licht, Lärm und Blut“ und malte, bewegt davon, Velázquez und Goya im Original gesehen zu haben, mehrere spanische Motive. Der gelbe Sand der Arena und die getupften Gesichter der Menge bilden die großen Flächen.",
  "manet-sea-view": "Das Meer vor Boulogne im Jahr 1864, Segelboote und ein Dampfer auf türkisfarbenem Wasser. Manet hatte sich in jenem Jahr beim Malen einer Seeschlacht des Amerikanischen Bürgerkriegs für das Meer zu interessieren begonnen; dies ist das ruhige Gegenstück dazu. Grünes Wasser und grauer Himmel teilen die Leinwand in zwei Hälften.",
  "manet-portrait-woman-black": "Ein Frauengesicht, um 1878 mit Strichen so weich wie Pastell gemalt. Zwischen schwarzem Schal und Hut und dem hellen Grund sind nur die Augen und die roten Lippen scharf. Manet machte damals viele schnelle Bildnisse von Pariserinnen, mehr am Eindruck als an der Ausführung interessiert.",
  "redon-still-life-flowers": "Redon, lange für seine schwarzen Kohlezeichnungen berühmt, entdeckte die Farbe erst nach dem fünfzigsten Lebensjahr und malte Blumen wie diese. Auf dieser Leinwand von 1905 scheint der Strauß auf pastellfarbenem Grund zu schweben. Er arbeitete nach echten Blumen, verwischte aber Vase und Hintergrund, bis das Stillleben geträumt wirkte.",
  "redon-flowers": "Ein kleines Blumenstück auf Karton von etwa 1867, als Redon jung war: roter Mohn und weiße Margeriten vor dunklem Grund. Es liegt vierzig Jahre vor seinem Ruhm als Kolorist, und der schwarze Grund kündigt seine Kohleperiode an. Die meisten Teile sind dunkel — fang bei den hellen Blüten an.",
  "renoir-two-sisters": "Eines von Renoirs beliebtesten Bildern, 1881 auf einer Terrasse über der Seine in Chatou bei Paris entstanden. Das Mädchen mit dem roten Hut und das Kind mit dem Blumenhut waren Modelle, keine echten Schwestern, und der Wollkorb auf ihrem Schoß liegt dort um seiner Farbe willen. Es wurde bald nach der Impressionistenausstellung verkauft; jede Ecke hat eine andere Farbe.",
  "renoir-acrobats-cirque-fernando": "Die Schwestern Wartenberg, die im Cirque Fernando am Montmartre auftraten, gemalt 1879. Die Mädchen waren vierzehn und siebzehn, hier beim Verbeugen, die vom Publikum geworfenen Orangen im Arm. Gelbe Kostüme und der orangefarbene Boden der Manege bilden warme Farbfelder.",
  "renoir-fruits-midi": "Früchte und Paprika aus Südfrankreich, 1881 nach Renoirs Reise ans Mittelmeer gemalt. In jenem Jahr sah er in Italien Raffael und begann, die Formen fester zu zeichnen; die klaren Umrisse der Früchte zeigen den Wandel. Rot, Gelb und Grün streuen über das weiße Tuch.",
  "renoir-chrysanthemums": "Ein Strauß Chrysanthemen, gemalt um 1881. Renoir sagte, Blumen zu malen „lasse das Gehirn ausruhen“, und schob sie zwischen die Bildnisse; hier modelliert er die Blütenblätter in dicker Farbe. Gelbe, weiße und rote Blüten drängen sich zusammen — die Teile nach Farbe zu sortieren erledigt die Arbeit.",
  "renoir-young-woman-sewing": "Eine Frau näht vor einem Blumenstrauß, gemalt 1879. Ihr Gesicht ist weich verwischt, während die Blumen dahinter die stärkste Farbe tragen. Renoir sagte damals, ein Bild solle „fröhlich, hübsch und schön“ sein, und genau das ist diese kleine Leinwand.",
  "renoir-woman-piano": "Eine Frau im weißen Kleid am Klavier, um 1875. Kerzen- und Fensterlicht färben das Weiß ihres Kleides blau, rosa und gelb, und die weißen Noten sind die hellste Stelle. Renoir zeigte das Bild auf der Impressionistenausstellung von 1876.",
  "renoir-lunch-restaurant-fournaise": "Ruderer beim Mittagessen auf der Terrasse des Restaurants Fournaise auf der Insel bei Chatou an der Seine, 1875. Renoir verkehrte dort regelmäßig und malte sechs Jahre später am selben Ort sein großes Frühstück der Ruderer. Der Fluss hinter dem Spalier und der weiße Tisch sind die hellen Teile.",
  "renoir-seascape": "Ein seltenes reines Seestück Renoirs, 1879 an der normannischen Küste gemalt. Keine Menschen, keine Boote: Wellen und Himmel in kurzen Strichen ineinandergerührt, nahe an der Abstraktion. Blau, Grün, Violett und Weiß verhaken sich im Wasser — auf diesem schweren Brett zählt die Form der Nasen.",
  "renoir-near-lake": "Ein Paar lehnt am Geländer eines Pavillons am See, um 1879. Wasser glitzert durch Spalier und Blätter, und die Figuren lösen sich halb in Lichtflecken auf. Das Bild stammt aus den Jahren, in denen Renoir am tiefsten in der impressionistischen Malweise steckte.",
  "renoir-alfred-sisley": "Renoirs Bildnis seines Freundes und Malerkollegen Sisley von 1876. Die beiden hatten sich in den 1860er Jahren im Atelier Gleyre kennengelernt und waren gemeinsam zum Malen in den Wald von Fontainebleau gezogen. Die entspannte Haltung rittlings auf dem Stuhl, der schwarze Mantel und der rote Grund schieben den Dargestellten nach vorn.",
  "courbet-mere-gregoire": "Courbets Bildnis einer Pariser Cafébesitzerin von 1855, hinter ihrem Tresen mit einer Blume, im Begriff, einen Gast zu begrüßen. Eine gewöhnliche Frau im Format eines Adelsporträts zu malen war seine Erklärung zum Realismus. Der Name stammt aus einem populären Lied; das Modell war eine echte Wirtin.",
  "courbet-rock-hautepierre": "Der Felsen von Hautepierre im Tal der Loue nahe Courbets Heimatstadt Ornans, gemalt um 1869. Er trug die Farbe mit dem Spachtel dick auf, um die Struktur des Gesteins aufzubauen; grüner Wald und blassgrauer Fels teilen die Leinwand von oben nach unten. Dieses Tal malte er in seinem Leben Dutzende Male.",
  "courbet-cliffs-sea-coast": "Morgengrauen an der Küste von Trouville in der Normandie, 1865. In jenem Sommer malte Courbet Dutzende Bilder aus nichts als Himmel und Wasser und eröffnete damit die Gattung des reinen Seestücks; dieses fügt eine Klippe hinzu. Blassrosa Himmel und graue Wellen bedecken weite Flächen — es gilt als schwer.",
  "delacroix-combat-giaour-hassan": "Nach Byrons Gedicht Der Giaur: Der christliche Giaur kämpft zu Pferd gegen den Türken Hassan, der seine Geliebte getötet hat, 1826 von Delacroix gemalt. Verkeilte Pferde, fliegende Gewänder und ein roter Turban bilden einen Strudel. Die Leidenschaft der romantischen Malerei steckt hier ganz drin.",
  "delacroix-lion-hunt": "Eine der Löwenjagden, die Delacroix bis in seine letzten Jahre immer wieder malte und in denen er Erinnerungen an seine Marokkoreise von 1832 mit Rubens' Jagdszenen verschmolz; diese Fassung stammt von 1860. Pferde, Löwen und Menschen verknoten sich zu einer Masse, und man muss hineinzoomen, um zu erkennen, wer wer ist. Rotes Tuch und ein weißes Pferd sind die Markierungen im dunklen Gewirr.",
  "delacroix-arab-horseman-attacked": "Ein kleines Bild von etwa 1849: An einem felsigen Hang springt ein Löwe ein Pferd und seinen Reiter an. Delacroix studierte die Bewegung der Löwenmuskeln, indem er sie in der Menagerie des Jardin des Plantes in Paris zeichnete. Das rote Gewand und der falbe Löwe brechen durch das Grau der Felsen.",
  "homer-herring-net": "Zwei Fischer holen 1885 vor Gloucester in Massachusetts Heringe ein. Das kleine Boot kippt in der Dünung, silberne Fische strömen aus dem Netz, und größere Schiffe ragen im Nebel dahinter auf. In jenem Jahr zog Homer an die Küste von Maine und malte für den Rest seines Lebens das Meer und seine Fischer.",
  "homer-croquet-scene": "Frauen und ein Herr spielen 1866 Krocket auf einem Rasen, kurz nach dem Bürgerkrieg — ein früher Homer. Krocket war groß in Mode, weil es zu den wenigen Spielen im Freien gehörte, die Männer und Frauen gemeinsam spielen konnten, und Homer malte fünf Bilder davon. Blaue, rote und weiße Kleider heben sich scharf vom Grün ab.",
  "homer-peach-blossoms": "Eine Frau sitzt 1878 unter einem blühenden Pfirsichbaum auf einer Farm im Staat New York. In jenem Jahr malte Homer eine helle Reihe von Landmädchen und Hirtinnen; weißes Kleid, rosa Blüten und tiefgrünes Feld geben die Farben des Frühlings. Es war die friedlichste Zeit des einstigen Kriegszeichners.",
  "whistler-coast-scene": "Ein Strand, den Whistler um 1884 auf ein kleines Holztäfelchen malte: graues Meer und Sand mit ein paar winzigen Gestalten darauf. Diese handtellergroßen Tafeln nannte er „Notizen“ und behandelte sie rein als Farbharmonien. Fast durchgehend Graubänder — ein schweres Puzzle.",
  "whistler-grey-silver": "Die Schornsteine und Boote von Battersea, von Whistlers Haus in Chelsea aus über die Themse gesehen, 1863. Ein frühes Beispiel seiner musikalischen, aus Farbnamen gebildeten Titel; er bestand darauf, ein Bild sei eine Anordnung von Farbe, keine Geschichte. Segel und Schornsteine zwischen grauem Wasser und silbrigem Himmel sind die Ankerpunkte.",
  "monet-boats-beach-etretat": "Auf den Kiesstrand von Étretat in der Normandie gezogene Fischerboote, Winter 1885. Stürme zwangen Monet mitunter, aus seinem Hotelfenster zu malen; hinten zeigt sich der berühmte Felsbogen. Dunkle Rümpfe, weiße Klippe und grünes Meer sind die drei Farben, die die Teile sortieren.",
  "monet-etretat": "Aus demselben Aufenthalt von 1885: der Strand von Étretat und die Falaise d'Amont im Norden. Courbet und Delacroix hatten diese Klippen zuvor gemalt; Monet malte sie über fünfzigmal aus verschiedenen Winkeln. Der Kontrast von weißer Klippe und grüntürkisem Meer trägt auch über 100 Teile hinaus.",
  "monet-departure-boats": "Fischer von Étretat setzen am Morgen rote Segel zur Ausfahrt, 1885. Am Fuß der Klippe links reihen sich strohgedeckte Bootsschuppen, und dreieckige Segel sprenkeln das Meer. Rote Segel und braune Dächer heben sich vom türkisfarbenen Wasser ab.",
  "jongkind-entrance-to-port": "Ein Segelschiff läuft in den Hafen von Honfleur in der Normandie ein, 1863 vom gebürtigen Niederländer Jongkind gemalt. Er brachte dem jungen Monet bei, Himmel und Wasser zu malen; Monet sagte, er sei derjenige gewesen, der ihm „endlich die Augen geöffnet“ habe. Große Wolken und Segel nehmen den größten Teil der Leinwand ein.",
  "jongkind-church-overschie": "Die Kirche von Overschie, einem Kanaldorf bei Rotterdam in Jongkinds heimatlichen Niederlanden, gemalt 1866. Turm und weiße Wolken spiegeln sich im Kanal, dazu ein kleines Boot — eine Fortsetzung der niederländischen Landschaftsmalerei des 17. Jahrhunderts. Die Spiegelung ist der Hinweis für die untere Hälfte.",
  "sargent-fountain": "Sargents Malerfreunde, das Ehepaar von Glehn, im Garten einer Villa in Frascati bei Rom, 1907: Jane malt an der Staffelei, während ihr Mann Wilfrid zusieht. Ihr weißes Kleid und die Gischt des Brunnens sind mit einzelnen Strichen hingesetzt. Der Porträtaufträge müde, malte er dies frei auf einer Reise mit Freunden.",
  "sargent-madame-paul-escudier": "1882 in Paris vom sechsundzwanzigjährigen Sargent gemalt: Eine Frau in Schwarz steht zwischen Vorhängen im Gegenlicht und verschmilzt mit dem Dunkel. Nur Gesicht, Hände und der weiße Vorhang sind hell, der Rest brauner Schatten — eine deutliche Schuld an Velázquez. Bei so vielen dunklen Teilen wird man über die Nasenform zusammensetzen.",
  "sargent-mrs-dyer": "Mary, Frau eines befreundeten amerikanischen Malers, 1880 von Sargent in Venedig gemalt. Über dem schwarzen Kleid schweben ein blasses Gesicht, rote Lippen und ein Ring an ihrer Hand. Er war vierundzwanzig und noch nicht berühmt und malte es als Geschenk für Freunde.",
  "sargent-mrs-deering": "Marion, Frau des Chicagoer Kaufmanns Charles Deering, im roten Kleid, 1888 von Sargent gemalt. Deering wurde sein lebenslanger Förderer, und dieses Bildnis markiert den Beginn ihrer Freundschaft. Weißer Spitzenkragen und roter Samt kontrastieren stark mit dem braunen Grund.",
  "sargent-under-cypress-trees": "Sargents Reisegefährten rasten 1909 im Schatten von Zypressen auf der griechischen Insel Korfu. Braune Stämme, grünes Laub und blaues Meer laufen in hohen senkrechten Bändern, gesprenkelt mit Lichtflecken. In späten Jahren schätzte er solche Reiseskizzen höher als seine Bildnisse.",
  "canaletto-terrace": "Eine erfundene Ansicht in der Art Canalettos aus dem Venedig des 18. Jahrhunderts: eine Terrasse unter einem Bogen mit Blick auf Kanal und Gebäude. Solche „Capricci“ setzten reale Orte neu zusammen und wurden von englischen Adligen als Andenken an die Grand Tour gekauft. Der dunkle Schatten des Bogens und der helle Himmel teilen das Bild.",
  "canaletto-portico-lantern": "Eine erfundene venezianische Szene von etwa 1745 aus dem Umkreis Canalettos: Durch einen Säulengang mit hängender Laterne erscheinen ein Kanal und eine Gondel. Die Architektur davor ist erdacht, während die Bauten dahinter dem wirklichen Venedig ähneln. Graue Steinsäulen und der blaue Himmel dahinter sind die beiden Hauptfarben.",
  "guardi-garden-palazzo-contarini": "Ein seltenes Gartenbild Guardis aus den späten 1770er Jahren: das Gelände eines venezianischen Palazzo mit Wegen, Statuen und Spaziergängern, hingesetzt mit seinem flirrenden Pinsel. Berühmt für Kanalansichten, malte er nur selten Gärten. Weiter Himmel, grüne Hecken und weiße Statuen führen durch die Teile.",
  "guardi-grand-canal": "Der Canal Grande in Venedig um 1760, Paläste und Gondeln im Wasser gespiegelt. Wo Canaletto die Stadt in präzisen Linien zeichnete, malte Guardi mit zitterndem Pinsel Licht und Luft — ein Jahrhundert vor den Impressionisten. Die Fensterreihen der Fassaden verraten, wohin jedes Teil gehört.",
  "guardi-ruined-archway": "Eine erfundene Szene aus Guardis letzten Jahren: Lagune und Boote, gesehen durch einen zerfallenen antiken Bogen. Ruinen waren im Europa des 18. Jahrhunderts Mode, und Guardi verwandelte reale venezianische Bauten gern in solche. Der braune Backstein des Bogens kontrastiert mit der Helligkeit des Himmels dahinter.",
  "hassam-new-york-street": "Die Fifth Avenue in New York unter Schnee, 1902 vom amerikanischen Impressionisten Hassam gemalt. Kutschen, Schirme und Laternen verschwimmen im Schneefall; er sah New York als „das amerikanische Paris“ und malte es als Serie. Grauer Schnee, braune Kutschen und roter Backstein sortieren die Teile.",
  "hassam-new-england-headlands": "Die felsige Küste und das Städtchen Gloucester in Massachusetts, 1899 von Hassam gemalt. Weiße Häuser, Felsen und eine blaue Bucht liegen im hellen Sonnenlicht, der Pinselstrich nahe am Pointillismus. Er verbrachte seine Sommer malend an der Küste Neuenglands, und dies ist eines der besten dieser Bilder.",
  "hassam-baileys-beach": "Der mondäne Strand von Newport in Rhode Island im Jahr 1901. Gras und Felsen der Landzunge fallen zu einem grünen Meer ab, kleine Gestalten stehen im Sand. Hassam malte mehrere Ansichten der sommerlichen Kolonie der Reichen von Newport.",
  "hassam-little-pond": "Ein Tümpel zwischen den Felsen von Appledore Island vor der Küste von Maine, 1890. Hassam verbrachte die Sommer auf der Insel, wo die Dichterin Celia Thaxter ihren Garten hatte, und malte dort Dutzende Bilder. Grauer Fels, grünes Gras und blauer Tümpel teilen sich sauber.",
  "hassam-el-zocodover": "Der Hauptplatz der Altstadt von Toledo, 1910 auf einer Spanienreise von Hassam gemalt. Menschen bewegen sich zwischen weiß getünchten Häusern, während das starke südliche Licht die Schatten blau färbt. Das Raster aus Fenstern und Balkonen legt fest, wohin die Teile gehören.",
  "monet-waterloo-bridge": "Eines der Themse-Bilder, die Monet ab 1899 bei drei Londonaufenthalten aus einem Fenster des Savoy Hotel malte. Die Waterloo Bridge und die Fabrikschlote am anderen Ufer lösen sich im violetten und orangen Licht des Nebels auf. Er liebte den Nebel und sagte, ohne ihn wäre London nicht schön.",
  "monet-charing-cross-bridge": "Aus derselben Londoner Serie: die Eisenbahnbrücke von Charing Cross mit der Silhouette des Parlaments dahinter, 1901. Zugrauch und Nebel verschmelzen, bis die Form fast verschwindet und nur Blau und Rosa bleiben. Ein schweres Brett, das man eher über die Farbe als über die Form löst.",
  "renoir-lucie-berard": "Lucie, jüngste Tochter der Bérards, Renoirs Förderer, gemalt 1883. Er verbrachte die Sommer im Haus der Familie in der Normandie und malte die Kinder viele Male. Weißes Kleid und helles Haar schweben auf blauem Grund, schlicht und leuchtend.",
  "degas-millinery-shop": "Eine Frau betrachtet in den 1880er Jahren Hüte in einem Pariser Putzmacherladen, gemalt von Degas. Er machte aus der Figur statt einer Kundin eine Modistin bei der Arbeit, und die farbigen Hüte sitzen wie Blumen am oberen Bildrand. In diesen Jahren entstanden über zwanzig solcher Hutmacherbilder.",
  "degas-cafe-singer": "Eine Sängerin auf der Bühne eines Pariser Café-concert, 1879 von unten gesehen. Das Rampenlicht wirft ihr Gesicht von unten in den Schatten, und die schwarz behandschuhte Hand setzt den Akzent zum Lied. Degas malte in diesen Jahren durchgehend das nächtliche Paris in Pastell und Öl.",
  "toulouse-lautrec-moulin-rouge": "Toulouse-Lautrecs berühmtestes Gemälde: das Innere des Kabaretts Moulin Rouge am Montmartre, 1892. Freunde sitzen um einen Tisch, der kleinwüchsige Lautrec selbst geht mit seinem Cousin dahinter vorbei, und die grüngesichtige Frau rechts ist die Sängerin May Milton. Jener rechte Streifen war einst abgeschnitten und wurde später wieder angesetzt.",
  "toulouse-lautrec-equestrienne": "Eine Kunstreiterin auf ihrem Pferd und der Zirkusdirektor mit der Peitsche im Cirque Fernando, um 1887. Der schräge Blick in die Manege hinab und das angeschnittene Publikum stammen von Degas und aus japanischen Holzschnitten. Das Bild soll im Eingang des Moulin Rouge gehangen haben.",
  "toulouse-lautrec-moulin-galette": "Den Tanzsaal am Montmartre, den Renoir dreizehn Jahre zuvor hell und heiter gemalt hatte, malte Lautrec 1889 neu — mit dunklen, gleichgültigen Gesichtern. Die Frauen am vorderen Tisch blicken zur Seite, statt zu tanzen, und der Boden dahinter verschwimmt. Sein Paris sieht die Langeweile hinter dem Vergnügen.",
  "toulouse-lautrec-ballet-dancers": "Tänzerinnen, die der zwanzigjährige Lautrec um 1885 direkt auf die Wand eines Montmartre-Kabaretts malte und die später vom Putz auf Leinwand übertragen wurden. Ein Frühwerk in der Art des von ihm bewunderten Degas, mit Tänzerinnen hinter der Bühne. Weiße Tutus und rote Wand sortieren die Teile.",
  "toulouse-lautrec-circus": "Eine Zirkusreiterin auf einem Schimmel, ein Clown umkreist die Manege, 1888 auf Pergament gemalt. Lautrec liebte den Zirkus sein Leben lang; 1899 wegen seiner Trunksucht in eine Klinik eingewiesen, zeichnete er neununddreißig Zirkusszenen aus dem Gedächtnis, um zu beweisen, dass er gesund genug zum Gehen war.",
  "cassatt-childs-bath": "Cassatts bekanntestes Bild: eine Mutter wäscht ihrem Kind die Füße, von oben gesehen, 1893. Gestreiftes Kleid, geblümter Teppich und das Wasser in der Schüssel überlagern sich als flache Muster nach Art japanischer Holzschnitte. Sie war die einzige Amerikanerin, die mit den Impressionisten ausstellte.",
  "cassatt-balcony": "Eine Frau liest um 1878 auf einem Gartenbalkon Zeitung, kurz nachdem Cassatt sich auf Einladung von Degas den Impressionisten angeschlossen hatte. Grünes Laub und weißes Kleid lösen sich im hellen Licht auf. Mehr als das Gesicht geben das Licht auf Blättern und Kleid die Hinweise.",
  "cassatt-after-bullfight": "Ein Stierkämpfer zündet sich eine Zigarette an, 1873 von Cassatt in Sevilla gemalt, bevor sie zu den Impressionisten stieß. Sie bereiste damals Europa, um die alten Meister zu studieren, und der dunkle Grund und die starken Kontraste erinnern an Velázquez. Das goldbestickte Kostüm ist der eine Glanzpunkt.",
  "rembrandt-old-man-gold": "Ein alter Mann mit schwarzer Kappe, goldener Kette und stählernem Ringkragen, 1631 vom fünfundzwanzigjährigen Rembrandt gemalt. Kein wirklicher Auftraggeber, sondern eine „Tronie“ — ein kostümierter Kopf nach einem Modell. Nur das Gesicht fängt Licht, alles Übrige ist Dunkelheit, also sind die meisten Teile schwarz.",
  "rembrandt-young-woman-door": "Aus Rembrandts Werkstatt, 1645: Eine junge Frau stützt die Hand auf eine offene Halbtür und blickt heraus. Rote Ärmel, weißer Kragen und das Braun des Rahmens schweben auf dunklem Grund; das Motiv einer über die Tür blickenden Gestalt war in den Niederlanden damals beliebt.",
  "hals-portrait-artist": "Ein Mann unter einem breiten schwarzen Hut blickt geradeaus, 1644 von Hals gemalt. Spuren einer Palette legen nahe, dass er Maler war, und Hals' rauer, schneller Pinselstrich ist im weißen Kragen und im Gesicht zu sehen. Schwarze Kleidung und grauer Grund bedecken den größten Teil der Leinwand.",
  "hals-portrait-lady": "Eine wohlhabende Niederländerin, 1627 von Hals gemalt. Ihre gestärkte weiße Halskrause und die Spitzenmanschetten sind vor dem schwarzen Kleid fein ausgearbeitet, und sie hält ein Paar Handschuhe. Die Falten der weißen Krause sind der entscheidende Hinweis beim Zusammensetzen.",
  "hals-rommel": "Ein Mann spielt beim Karneval auf der Straße den Rommelpot, eine Topftrommel, umringt von lachenden Kindern — aus Hals' Werkstatt, um 1630. Die Mütze mit dem Fuchsschwanz und die grinsenden Gesichter zeigen Hals' Gabe für den erhaschten Ausdruck. Sechs Gesichter dienen jeweils als Merkzeichen für die Teile.",
  "ingres-amedee": "Ein junger Graf, den Ingres ab 1823 über drei Jahre hinweg malte. Schwarzer Frack, Orden und ein roter Samtsessel sind so glatt wiedergegeben, dass kein Pinselstrich sichtbar wird. Ingres nannte es das beste seiner Bildnisse.",
  "modigliani-jacques-berthe-lipchitz": "Der Bildhauer Jacques Lipchitz und seine Frau Berthe, 1916 von ihrem Freund Modigliani gemalt — sein einziges Doppelbildnis. Lipchitz gab es in Auftrag, um dem mittellosen Maler zu helfen, und überredete ihn, zwei Wochen daran zu arbeiten, statt an einem Tag fertig zu werden. Langgezogene Gesichter und Mandelaugen sind Modiglianis Handschrift.",
  "modigliani-madam-pompadour": "Modiglianis Geliebte, die englische Dichterin Beatrice Hastings, mit extravagantem Hut, 1915. Der auf die Leinwand geschriebene Titel ist ein Scherz, der sie mit der Mätresse Ludwigs XV. vergleicht. Rote Wand, schwarzer Hut und langer Hals zerfallen in einfache Flächen.",
  "modigliani-portrait-woman": "Eine Frau auf Karton, um 1917: rotes Haar, langer Hals und Augen ohne Pupillen — alles typisch Modigliani. Er soll Modellen gesagt haben, er male ihre Pupillen, „wenn ich deine Seele kenne“. Roter Hintergrund und braunes Kleid sind weite Flächen, also fang beim Gesicht an.",
  "morisot-woman-her-toilette": "Eine Frau ordnet vor dem Spiegel ihr Haar, von hinten gesehen, um 1875 von Morisot gemalt. Weiß, Silbergrau und blasses Rosa mischen sich in schnellen, leichten Strichen, bis Spiegel, Kleid und Haut ineinander verschwimmen. Morisot war Manets Schwägerin und Gründungsmitglied der Impressionisten.",
  "morisot-woman-garden": "Eine Frau im Garten von Morisots Villa in Bougival, 1882 — grünes Laub und weißes Kleid so verflochten, dass die Gestalt Teil des Gartens zu sein scheint. Sie malte zu Hause, während sie ihre Tochter Julie großzog, und ihr Pinselstrich ist der freieste aller Impressionisten.",
  "morisot-young-girl-hat": "Ein Mädchen mit weißem Hut, roten Wangen und rotem Haar vor grauem Grund, 1892 von Morisot gemalt. In ihren letzten Jahren arbeitete sie mit längeren Strichen und festeren Formen, und der Umriss des Gesichts ist hier klar. Der schlichte Hintergrund heißt: mit Gesicht und Hut anfangen.",
  "morisot-foret-de-compiegne": "Licht fällt zwischen die Bäume des Waldes von Compiègne nördlich von Paris, 1885 von Morisot gemalt. Stämme, Laub und Gras mischen sich in kurzen grünen und gelben Strichen, was es schwer macht — doch die Senkrechten der Stämme zeigen, wohin die Teile gehören.",
  "greco-saint-martin-beggar": "Um 1597 für eine Kapelle in Toledo gemalt: Der römische Soldat Martin zerteilt mit dem Schwert seinen Mantel, um ihn mit einem nackten Bettler zu teilen. Langgezogene Gestalten, ein Schimmel und ein Gewitterhimmel sind El Grecos Kennzeichen, und die Stadt Toledo erscheint klein unter den Hufen des Pferdes.",
  "rousseau-sawmill": "Ein Sägewerk und Schornsteine am Rand von Paris, um 1893 vom autodidaktischen Zollbeamten Henri Rousseau gemalt. Berühmt für seine Dschungelbilder, malte er auch viele gewöhnliche Ansichten rund um Paris und zeichnete jeden Baum mit kindlicher Sorgfalt. Weiße Mauern, grauer Himmel und grüne Bäume bilden einfache Flächen.",
  "bonheur-cattle-rest-hillside": "Rinder ruhen auf einer Alpenweide, 1885 von Rosa Bonheur gemalt, der berühmtesten Malerin des 19. Jahrhunderts. Um Tiere genau zeichnen zu können, verkehrte sie in Schlachthöfen und auf Viehmärkten und ließ sich die Polizeierlaubnis ausstellen, die eine Frau damals zum Tragen von Hosen brauchte. Weiße und rote Rinder liegen im Grünen.",
  "marc-bewitched-mill": "Ein Mühlendorf in Südtirol, 1913 vom deutschen Expressionisten Franz Marc gemalt. Menschen, Tiere, Häuser und Bäume sind wie Glasfenster in regenbogenfarbene Facetten zerlegt. Im Jahr darauf zog er in den Krieg und fiel 1916 bei Verdun.",
  "oudry-still-life-monkey": "Ein Stillleben von 1724 von Oudry, dem Maler Ludwigs XV.: Ein Affe greift zwischen Blumen und Früchten auf einem Steinsims. Bekannt wurde er mit den Hunden des Königs und den Tieren der königlichen Menagerie, und dies ist dekorative Malerei in ihrer üppigsten Form. Rote Früchte, weiße Blüten und der braune Affe markieren den dunklen Grund.",
  "hiroshige-hamamatsu": "Hamamatsu aus Hiroshiges kleinformatigen Dreiundfünfzig Stationen des Tōkaidō, der Straße zwischen Edo und Kyoto, um 1837. Reisende wärmen sich unter einer Kiefer an einem Feuer, während in der Ferne die Burg von Hamamatsu erscheint. Ukiyo-e-Drucke mit flacher Farbe und klaren Konturen eignen sich gut für Puzzles.",
  "hiroshige-mitsuke": "Die Überquerung der Sandbänke des Tenryū-Flusses mit der Fähre bei Mitsuke, der achtundzwanzigsten Station des Tōkaidō. Der Fluss war so breit, dass Reisende zweimal das Boot wechselten; Hiroshige schichtet ferne Boote im Dunst hinter die Fährleute im Vordergrund und erzeugt so Tiefe. Grauer Dunst, blaues Wasser und gelbe Sandbank bilden die Schichten.",
  "hiroshige-mishima": "Mishima aus den großformatigen Dreiundfünfzig Stationen des Tōkaidō von 1833, die Hiroshige berühmt machten. Im Morgennebel bleiben Schreintor und Dorf nur als graue Silhouetten; allein die Sänfte und der Reiter im Vordergrund haben Farbe. Der Nebel, von einem einzigen verlaufenden Druckstock gedruckt, ist der technische Stolz dieses Blatts.",
  "hiroshige-arai": "Arai, die Station des Tōkaidō mit einer Grenzsperre, zeigt Reisende, die den Hamana-See mit dem Boot überqueren. Die Kontrolle an der Sperre war streng und von Reisenden gefürchtet. Das Dach des großen Boots, blaue Wellen und ein weißer Berg in der Ferne teilen sich in einfache Flächen.",
  "hiroshige-maisaka": "Segelboote überqueren die Imagiri-Mündung des Hamana-Sees bei der Station Maisaka. Hiroshige setzt weiße Segel, blaues Wasser und einen fernen roten Fuji in ein Bild, um den Reiz des Reisens einzufangen. Die Dreiecke der Segel sind gute Anhaltspunkte für die Teile.",
  "hiroshige-miyanokoshi": "Miyanokoshi aus den Neunundsechzig Stationen des Kisokaidō, die Hiroshige sich mit Eisen teilte: Eine Familie überquert im Mondlicht eine Brücke unter der Silhouette eines großen Baumes. Als Nachtstück löst es sich in schwarzen Baum, indigofarbenen Himmel und mondgelbes Wasser auf. Eines von Hiroshiges schönsten Nachtbildern.",
  "hiroshige-seba": "Eine Vollmondnacht an der Station Seba am Kisokaidō: Ein Floß und ein Boot treiben einen schilfdichten Fluss hinab. Mond, Weide und das Licht auf dem Wasser machen es zu einem der lyrischsten aller Blätter Hiroshiges. Indigofarbener Himmel, gelber Mond und grünes Schilf sortieren die Teile.",
  "hiroshige-snow-benzaiten-shrine": "Schnee auf dem Benzaiten-Schrein am Inokashira-Teich vor Edo, um 1844. Weißer Schnee liegt dick auf Dächern, Bäumen und Brücke, während allein das Wasser tiefes Indigo bleibt. Bei so viel Weiß werden viele Teile über die Form zusammengesetzt.",
  "hiroshige-kanbara": "Vielleicht das beliebteste aller Blätter Hiroshiges: Drei Gestalten gehen bei nächtlichem Schneefall eine Hangstraße in Kanbara entlang. Das wirkliche Kanbara ist ein mildes Küstendorf, dieser schwere Schnee also Hiroshiges Erfindung. Schwarzer Himmel, weißer Schnee und graue Dächer treffen sich in drei stillen Tönen.",
  "hiroshige-shirasuka": "Aus einer Tōkaidō-Serie von etwa 1847: der Blick aufs Meer vom Shiomi-Hang bei der Station Shirasuka. Der Zug eines Daimyō steigt die Hangstraße hinab, während sich unten das blaue Meer ausbreitet. Roter Hang, grüne Kiefern und blaues Meer ergeben einen scharfen Kontrast.",
  "hokusai-shower-below-summit": "Das Gegenstück zum Roten Fuji in Hokusais Sechsunddreißig Ansichten des Berges Fuji: Unterhalb des Berges schlägt ein Blitz ein, während der Gipfel in den klaren Himmel ragt. Der Blitz ist als roter Zickzack über die schwarzen unteren Hänge gezeichnet. Ist der Rote Fuji der Morgen, so ist dies ein Sommergewitter am Nachmittag.",
  "hokusai-hara": "Die Station Hara aus einer kleinen Tōkaidō-Serie, die Hokusai um 1806 schuf — dreißig Jahre vor Hiroshiges. Reisende blicken auf den Berg Fuji, der über den Bildrand hinausragt. Wie in der frühen Ukiyo-e-Landschaft sind die Figuren groß und die Farben weich.",
  "hokusai-odawara": "Odawara aus derselben kleinen Tōkaidō-Serie Hokusais, mit Reisenden auf der Küstenstraße und der Burg im Blick. In dieser Zeit war Hokusai vor allem in Figuren stark, und die Landschaft kam eher einer Kulisse gleich. Blaues Meer und gelbe Straße sind die beiden Achsen für die Teile.",
  "hokusai-chrysanthemum-horsefly": "Aus Hokusais Serie Große Blumen von etwa 1831: Eine Bremse schwirrt zwischen roten und gelben Chrysanthemen. Mit siebzig eröffnete er mit seinen Blumen-und-Vogel-Blättern ein neues Genre, und die bildfüllenden Blüten lesen sich wie eine Ziertafel. Sortiere die Teile nach Blütenfarbe.",
  "utamaro-courtesan-arihara-tsuruya": "Die Kurtisane Arihara aus dem Haus Tsuruya im Yoshiwara mit zwei jungen Dienerinnen, um 1797. Muster prächtiger Kimonos und Haarschmuck füllen das Bild vor einem leeren Grund. Utamaro ist für seine Nahsichten weiblicher Gesichter berühmt.",
  "utamaro-mirror": "Eine Frau schminkt sich vor dem Spiegel, aus Utamaros Serie Acht Ansichten von Teehausfrauen, um 1795. Das Format der „Acht Ansichten“ stammt aus der chinesischen Landschaftsmalerei; er machte daraus Szenen aus dem Alltag der Frauen. Gelber Grund, schwarzes Haar und der runde Spiegel ergeben einfache Teile.",
  "utamaro-reflective-love": "Aus Utamaros Meisterserie Anthologie der Gedichte: Das Kapitel der Liebe — ein großer Frauenkopf, in Liebesgedanken versunken. Ein Luxusdruck, dessen Hintergrund einst von Glimmer schimmerte. Das Gesicht ist mit den denkbar wenigsten Linien gezeichnet, also sind Haar und Kragen die Schlüssel.",
  "kuniyoshi-asakusa-imado": "Das Flussufer bei Asakusa Imado aus Kuniyoshis Serie berühmter Orte in Edo, um 1832. Rauch aus Ziegelöfen steigt in den Himmel, und Boote treiben auf dem Sumida. Versuche mit westlicher Perspektive kennzeichnen diese Serie.",
  "kuniyoshi-kasumigaseki": "Kasumigaseki aus derselben Serie: eine Hangstraße zwischen Daimyō-Residenzen nahe der Burg von Edo mit Blick aufs Meer. Der Ort ist heute Tokios Regierungsviertel. Der blaue Verlauf des Himmels und weiße Mauern ordnen die Teile.",
  "kuniyoshi-hara": "Ein ungewöhnliches Blatt Kuniyoshis von etwa 1830, das drei Tōkaidō-Stationen in einem Bild vereint. Oben ragt der Fuji auf, darunter ziehen sich Dörfer und Straße hin. Eine seltene Landschaft von einem Künstler, der für Kriegerblätter berühmt war.",
  "kuniyoshi-hu-sanniang": "Die Kriegerin Hu Sanniang aus der Serie der 108 Helden vom Ufer der Flüsse, die Kuniyoshi berühmt machte. Sie führt zwei Schwerter und streckt einen Gegner nieder — eine Szene voller Bewegung; die Serie löste eine Mode für Kriegerblätter aus. Die Muster ihrer Rüstung unterscheiden sich von Teil zu Teil.",
  "kunisada-viewing-maple-trees": "Eine herbstliche Ahornschau, 1835 von Kunisada gemalt, auch Toyokuni III. genannt. Frauen picknicken unter roten Ahornen in Kimonos, die so leuchten wie das Laub. Kunisada war der produktivste Blattentwerfer der späten Edo-Zeit.",
  "kunisada-crouching-tiger": "Ein Tiger auf einem quadratischen Shikishi-Blatt von Kunisada, 1830. In Japan gab es keine Tiger, also arbeiteten die Künstler nach Katzen und chinesischen Bildern — daher wirkt das Gesicht katzenhaft. Die Richtung der Streifen zeigt, wohin jedes Teil gehört.",
  "kunisada-shirabyoshi-dancer": "Eine Shirabyōshi-Tänzerin von Kunisada, um 1830: ein überliefertes Motiv — eine Frau in männlicher Hoftracht tanzt mit einer Trommel in einem Boot. Die Gestalt sitzt in einem runden Fensterrahmen, eine ungewöhnliche Komposition. Schwarze Kappe, rotes Gewand und weißes Gesicht verankern die Teile.",
  "kunisada-landscape-mist": "Ein seltenes Landschaftsblatt Kunisadas von etwa 1832: ein Flussdorf und Berge im Dunst, in blauen Abstufungen gedruckt. Preußischblau, neu aus dem Westen eingeführt, war in Mode, daher ist das ganze Blatt blau. Die dunstigen Partien geben wenig Hinweise und sind schwer.",
  "kunisada2-kiritsubo": "Kiritsubo, das erste der vierundfünfzig Kapitel der Geschichte vom Prinzen Genji, aus einer Kartenserie Kunisadas II. von 1857. Hofdamen versammeln sich unter Kirschblüten, der Kapitelname steht auf der Karte darüber. Dichte Farbe und viel Muster geben jedem Teil reichlich Information.",
  "eisen-view-miyanoshita-hot": "Miyanoshita aus Eisens Serie über die heißen Quellen von Hakone aus den 1820er Jahren: Gasthäuser in den Bergen und eine vom Quellwasser dampfende Schlucht. Ein Luxusdruck, einst mit Metallpigment gehöht. Grüne Berge und braune Dächer sortieren die Teile.",
  "eisen-ferryboat-crossing-sumida": "Eine Fähre auf dem Sumida auf einem quadratischen Shikishi-Blatt von Eisen aus den 1820er Jahren. Fahrgäste im Boot und das Dorf am anderen Ufer fügen sich in den kleinen Rahmen, dazu breite blaue Wellen. Eisen ist für schwüle Schönheiten berühmt, hinterließ aber auch viele Landschaften.",
  "eisen-view-mount-fuji": "Menschen auf der Veranda eines Teehauses, dahinter der Berg Fuji, von Eisen aus den 1820er Jahren. Große Figuren im Vordergrund und ein kleiner ferner Fuji ergeben eine klare Perspektive. Die rote Teehausmatte kontrastiert mit dem blauen Berg.",
  "eisen-distant-view-snow": "Der verschneite Sumida aus der Ferne gesehen, von Eisen aus den 1840er Jahren. Drei Bänder — weißer Schnee, indigofarbener Fluss und grauer Himmel — durchziehen das Bild, gesprenkelt mit kleinen Booten. So schlicht es ist: hier zählen die Nasenformen.",
  "eisen-snow-sumida-river": "Ein Aizuri-Blatt der frühen 1830er Jahre, allein mit Preußischblau gedruckt: Bäume und Boote auf dem verschneiten Sumida, nur in Blauabstufungen wiedergegeben. Ein eigenes Genre, aus der Mode für das importierte Pigment entstanden. Eine einzige Farbe macht es schwer, doch die Formen der Bäume sind der Hinweis.",
  "eisen-nojiri-bridge": "Die Brücke über den Ina-Fluss bei Nojiri aus Eisens Anteil an der Kisokaidō-Serie: Reisende überqueren eine hohe Holzbrücke über einer tiefen Schlucht. Grüne Berge, blauer Fluss und die braunen Linien der Brücke sind deutlich. Eines der besten Blätter aus Eisens Beitrag zu der Serie, die er sich mit Hiroshige teilte.",
  "harunobu-evening-snow-floss": "Aus den Acht Ansichten des Wohnzimmers von 1766 von Harunobu, dem Künstler, der den vollfarbigen Nishiki-e-Druck zur Vollendung brachte. Der Witz der Serie liegt darin, den „Abendschnee“ der chinesischen Acht Ansichten in Frauen zu verwandeln, die drinnen Seidenwatte zupfen. Blasse Farben und feine Linien ergeben ein elegantes Blatt.",
  "harunobu-double-cherry": "Die Kurtisane Motoura unter einem Zweig gefüllter Kirschblüten, von Harunobu um 1768. Die schlanke, jugendliche Gestalt ist typisch für seine Schönheiten, und die Blüten füllen den Grund hinter ihr. Rosa Blüten und der helle Kimono fließen sanft ineinander.",
  "harunobu-evening-bell-clock": "Aus denselben Acht Ansichten des Wohnzimmers: Aus der „Abendglocke“ des Tempels wird eine Uhr im Zimmer, mit Frauen neben einem westlichen Zeitmesser. Es zeigt, wie selten und kostbar eine Uhr im Japan des 18. Jahrhunderts war. Grauer Raum und helle Gewänder halten es still.",
  "kiyonaga-third-month": "Der dritte Monat aus Kiyonagas Serie über die zwölf Monate im Vergnügungsviertel von Shinagawa, um 1784, ein großes Diptychon. Frauen bewirten Gäste in einem Teehaus am Meer an einem Frühlingstag voller Kirschblüten. Kiyonagas hochgewachsene, elegante Gestalten waren das Ideal ihrer Zeit.",
  "kiyonaga-carrying-lantern-decorated": "Frauen tragen mit Blumen geschmückte Laternen, von Kiyonaga aus dem Jahr 1780. Es hält den Brauch fest, bei Sommerfesten mit blumengeschmückten Laternen zu gehen; weiße Gesichter und farbige Kimonos schweben hell auf offenem Grund.",
  "kiyonaga-sixth-month": "Der sechste Monat aus einer kleinen Zwölf-Monate-Serie Kiyonagas, um 1779: Frauen kühlen sich an einem heißen Sommerabend auf der Veranda ab. Leichte Sommerkimonos und grüne Rollos tragen die Jahreszeit. Ein kleines Blatt, am besten mit wenigen Teilen.",
  "kiyonaga-actors-matsumoto-koshiro": "Zwei Kabuki-Schauspieler auf der Bühne, von Kiyonaga aus dem Jahr 1788. Ein seltenes Schauspielerblatt von einem Künstler, der für Schönheiten berühmt war, mit prächtigen Kostümen und Kirschblüten, die eine Szene des Stücks nachstellen. Kabuki-Blätter waren die Starfotos ihrer Zeit.",
  "toulouse-lautrec-concert": "Ein Lithografieplakat von 1896, das Lautrec als Werbung für eine amerikanische Tintenfirma schuf: ein Paar auf Theatersitzen. Das rote Haar der Frau, der schwarze Hut des Mannes und das leere weiße Papier sind kühn gegeneinandergesetzt. Lautrec erhob als Erster das Plakat zur Kunst.",
  "toulouse-lautrec-photographer-sescau": "Ein Plakat für das Atelier von Lautrecs Freund, dem Fotografen Paul Sescau, 1896. Eine Frau in Rot posiert vor der Kamera, während Sescau unter dem schwarzen Tuch auslöst. Gelber Grund, rote Schrift und grüne Kleidung sind so kühn, wie ein Plakat sein soll.",
  "toulouse-lautrec-elsa": "Elsa, eine Wienerin in Paris, in einer Lithografie von 1897: blaues Kleid und rotes Haar in wogenden Linien gezeichnet. Lautrec hielt die Frauen der Montmartre-Cafés eine nach der anderen in Drucken fest. Bei viel leerem Papier drängen sich die Teile in der Figur.",
  "toulouse-lautrec-jockey": "Das erste Blatt einer Lithografieserie über den Rennsport, die Lautrec 1899 nach seiner Entlassung aus der Klinik schuf. Pferd und Jockey galoppieren von hinten gesehen vom Betrachter fort, die Muskeln des braunen Pferdes in dicken Strichen erfasst. Zwei Jahre später starb er.",
  "toulouse-lautrec-englishman-moulin-rouge": "Der englische Maler Warner, Stammgast im Moulin Rouge, im Gespräch mit zwei Frauen, in einer Lithografie von 1892. Der braune Mantel des Mannes und die Frauen vor Grün zerfallen in einfache Felder, und seine Silhouette beherrscht das Blatt.",
  "cheret-palais-de-glace": "Eine Werbung für die überdachte Eisbahn an den Champs-Élysées, 1891, von Jules Chéret, dem „Vater des Plakats“. Eine lachende Frau im roten Kleid läuft Schlittschuh, hinter ihr ein Herr in Schwarz. Chérets fröhliche Frauen, „Chérettes“ genannt, füllten die Straßen von Paris.",
  "cheret-etendard-francais": "Ein Plakat für einen Fahrradhersteller, 1891: Eine Frau im Kleid in den Nationalfarben schwenkt neben einem Fahrrad die französische Flagge. Es fängt die Pariser Fahrradbegeisterung der 1890er Jahre und ihren Patriotismus auf einem Blatt ein. Rot, Blau und Weiß teilen die Fläche.",
  "bonnard-france-champagne": "Bonnards erstes Plakat, 1889 mit zweiundzwanzig Jahren für ein Champagnerhaus geschaffen: Das Kleid einer Frau schäumt wie Perlen über das gelbe Blatt. Der Erzählung nach sah Lautrec es auf der Straße und ließ sich davon anregen, selbst Plakate zu machen.",
  "penfield-will-you-help": "Ein Kriegsplakat von 1917 des Amerikaners Edward Penfield: Französische Frauen ziehen einen Pflug, während die Männer an der Front sind. Es rief die Amerikaner auf, Weizen zu sparen, um Frankreich zu helfen. Kräftige Konturen und flache Farbe halten es so schlicht wie einen Holzschnitt.",
  "morris-swan-house-carpet": "Ein handgeknüpfter Teppich, den William Morris 1883 für Swan House in Chelsea, London, entwarf. Der Aufbau eines persischen Teppichs, gefüllt mit englischen Gartenblumen, roter Grund in blauer Bordüre. Das Muster wiederholt sich, doch das mittlere Medaillon gibt einen festen Bezugspunkt.",
  "morris-peacock-dragon": "Ein Wollstoff, den Morris 1878 entwarf: Pfauen und Drachen stehen sich in einem gespiegelten Rapport gegenüber. Angeregt von mittelalterlichen italienischen und nahöstlichen Textilien, hing er an den Salonwänden von Morris' eigenem Kelmscott House. Weil das Muster spiegelt, achte genau auf links und rechts.",
  "morris-tulip-rose": "Ein Textil, das Morris 1876 entwarf: Tulpen und Rosen, verschlungen in gewundenen Ranken. Morris sagte, ein Muster solle „aussehen, als wachse es“, und dieser Entwurf folgt der Regel genau. Rote Blüten und grüne Blätter greifen ineinander, was die Teilegrenzen verwickelt macht.",
  "morris-windrush": "Ein bedruckter Baumwollstoff von 1883, benannt nach dem Fluss Windrush, der nahe Kelmscott fließt. Große Blätter und kleine Blüten sind auf grünem Grund im Modeldruck aufgebracht; Morris färbte mit natürlichem Indigo und Krapp statt mit chemischen Farbstoffen. Die Richtung der Blattadern ist der Hinweis beim Zusammensetzen.",
  "morris-acanthus": "Akanthusblätter, 1876 von Morris entworfen — das Blatt griechischer Kapitelle, zu großen Wirbeln angeschwollen. Die überlappenden Blätter erscheinen nur in Abstufungen eines Rots, was es schwer macht, doch die Richtung der Blattspitzen hilft. Als Tapete brauchte der Entwurf mehr Druckstöcke als jeder andere von Morris.",
  "morris-oak": "Ein Seidendamast, den Morris 1881 entwarf: Eichenblätter und Eicheln, in grünen Grund gewebt. Beim Damast zeigt sich das Muster allein über den Glanz der Fäden, weshalb es auf einer Fotografie zurückhaltend bleibt. Der gezackte Umriss der Blätter ist der Hinweis.",
  "morris-corncockle": "Ein bedruckter Baumwollstoff von 1883 nach der Kornrade, einer rosa Wildblume der Weizenfelder. Grüne Blätter, rosa Blüten und kleine blaue Blumen auf weißem Grund machen ihn zu einem der hellsten Entwürfe von Morris. Die rosa Blüten sitzen in gleichmäßigen Abständen und dienen als Bezugspunkte.",
  "morris-snakeshead": "Ein Textil von 1876 nach der Schachbrettblume mit ihrer karierten Blüte. Stark vom indischen Chintz beeinflusst, drängt es rote Blüten auf indigofarbenen Grund und gehörte zu Morris' eigenen Lieblingsentwürfen. Das dichte Muster gibt jedem Teil reichlich Anhaltspunkte.",
  "morris-tulip": "Ein früher bedruckter Baumwollstoff, den Morris 1875 entwarf: weiße Tulpen und Blätter, die sich über blauem Grund kräuseln. Er hatte gerade seine eigene Färberei eröffnet, um mit Indigo zu experimentieren, und das Blau dieses Stoffs ist das Ergebnis. Bei einfarbigem Grund setzt man über die Umrisse der Tulpen zusammen.",
  "dresser-panel": "Ein Woll- und Seidenstoff, 1871 vom britischen Gestalter Christopher Dresser entworfen: geometrische Blüten wiederholen sich in einem Raster auf rotem Grund. Als ausgebildeter Botaniker führte er Blumen auf Geometrie zurück, statt sie abzumalen, und war ein Wegbereiter darin, japanische Kunst im Westen bekannt zu machen. Das regelmäßige Muster löst man Feld für Feld.",
  "mondrian-lozenge-composition-yellow": "Eine quadratische Leinwand, auf die Ecke gestellt als Raute gehängt, 1921. Schwarze Senkrechte und Waagerechte mit Flächen in Grundfarben bilden Mondrians „Neoplastizismus“; er glaubte, in dieser Schlichtheit stecke die Ordnung des Universums. Überwiegend weiß, gehört es zu den schwersten Puzzles hier.",
  "mondrian-farm-near-duivendrecht": "Ein Bauernhof vor Amsterdam, um 1916 gemalt, bevor sich Mondrian der Abstraktion zuwandte. Kahle Zweige vernetzen den Abendhimmel, und das Bauernhaus spiegelt sich im Wasser. Das Geflecht der Zweige ist als Ursprung der kommenden schwarzen Raster faszinierend.",
  "munch-girl-by-window": "1893 gemalt, im selben Jahr wie Der Schrei: Ein Mädchen im weißen Nachthemd blickt aus einem dunklen Zimmer in die blaue Nacht. Mondlicht wirft den Schatten des Fensters auf den Boden, und ihr Rücken trägt Angst und Sehnsucht zugleich. Eine schlichte Komposition aus Blau, Schwarz und Weiß.",
  "munch-madonna": "Munchs Lithografie von 1895 nach seinem Gemälde Madonna, von Hand koloriert. Die Frau mit geschlossenen Augen ist von einer Bordüre aus Samenzellen und einem Fötus gerahmt — Munchs Sinnbild für Liebe und Tod in einem Bild. Der rote Heiligenschein auf schwarzem Grund verankert die Teile.",
  "matisse-woman-before-aquarium": "Eine Frau blickt in ein Goldfischglas, 1921 von Matisse in Nizza gemalt. In diesen Jahren malte er aus seinen Hotelzimmern in Nizza Fenster, Muster und Frauen in ruhiger Farbe, und Goldfische waren ein Lieblingsmotiv. Grüne Wand, rote Fische und weißes Papier sortieren die Teile.",
  "matisse-still-life-geranium": "Eine Topfgeranie mit Früchten und kleinen Skulpturen, 1906 in Matisse' fauvistischer Zeit gemalt. Grün, Rosa und Orange sind grob aufgetragen, und der Hintergrund wirkt unfertig. Ein Bild aus dem Moment, in dem sich die Farbe von der Form löste.",
  "matisse-apples": "Ein Teller Äpfel auf einem runden Tisch, von oben gesehen, 1916. Rosa Tisch, grüne Äpfel und schwarzer Grund teilen sich in große Felder, nah an der Abstraktion. Im Ersten Weltkrieg wurde Matisse' Malerei so schlicht und streng.",
  "matisse-woman-rose-divan": "Eine Frau liegt auf einem gemusterten Diwan, aus Matisse' Nizzaer Zeit im Jahr 1921. Die roten Blüten des Diwans, der Fliesenboden und ihre gestreifte Hose überlagern sich, bis die ganze Fläche als Ornament zu lesen ist. Bei so viel Muster ist jedes Teil reich an Hinweisen.",
  "cole-distant-view-niagara": "Die Niagarafälle, 1830 von Thomas Cole gemalt, dem Begründer der Hudson River School. Zwei Indigene stehen vorn auf den Felsen, und ein Regenbogen spannt sich über die Fälle. Cole malte die amerikanische Wildnis vor ihrer Erschließung und trat für ihren Erhalt ein.",
  "cole-new-england-scenery": "Eine ideale Landschaft von 1839, die Fluss, Wald, Brücke und Kirche Neuenglands zu einer Ansicht versammelt. Kein wirklicher Ort, sondern eine Zusammenstellung, die das Ideal des amerikanischen Landes malt. Das Grün des großen Baums, der Fluss und ferne Berge bilden die Schichten.",
  "bierstadt-mountain-brook": "Ein Waldbach, 1863 vom gebürtigen Deutschen und späteren Amerikaner Albert Bierstadt gemalt. Berühmt für großartige Panoramen der Rocky Mountains, konzentriert er sich hier auf das Licht zwischen moosigen Felsen und Bäumen. Dunkler Wald, helles Wasser und brauner Fels sortieren die Teile.",
  "jakuchu-red-parrot-branch": "Ein Holzschnitt von etwa 1905 nach einem Gemälde des Kyotoer Künstlers Itō Jakuchū aus dem 18. Jahrhundert. Ein roter Papagei und ein Zweig heben sich von schwarzem Grund ab; Jakuchū ist für außerordentlich detaillierte Vögel und Hähne berühmt. Bei schwarzem Grund beginnt man mit dem roten Vogel und den Blättern.",
  "danwon-seodang": "Das bekannteste Blatt aus Kim Hong-dos Album des Alltagslebens. Ein Junge, den der Lehrer eben gezüchtigt hat, wischt sich die Tränen, während seine Mitschüler ihr Kichern verbergen und der Lehrer eine strenge Miene aufsetzt. Ganz ohne Hintergrund sind die Figuren in einem lockeren Kreis angeordnet, sodass ein einziger Augenblick des Lachens in der Luft zu hängen scheint.",
  "danwon-bballaeteo": "Frauen klopfen die Wäsche auf den Steinen eines Bachs, während eine andere ihr Haar kämmt, und hinter einem Felsblock verbirgt ein Herr sein Gesicht halb hinter dem Fächer, während er späht. Kim Hong-do macht aus der gespielten Gleichgültigkeit des Gelehrten einen sanften Scherz und hält eine Arbeit am Flussufer mit wenigen schlichten, sicheren Linien fest.",
  "danwon-byeotajak": "Bauern dreschen Reis, indem sie die Garben gegen einen Balken schlagen, während ein Mann, der unverkennbar der Gutsherr ist, mit langer Pfeife im Mund auf einer Strohmatte oben auf dem Haufen liegt. Indem Kim Hong-do die sich mühenden Körper neben den müßigen Aufseher setzt, zeigt er das Landleben der späten Joseon-Zeit mit wissendem Lächeln.",
  "danwon-giwaigi": "Ein Haus entsteht: Der Dachdecker fängt die von unten hochgeworfenen Ziegel, ein Zimmermann prüft einen Pfosten mit dem Senklot, ein anderer sägt Holz. Kim Hong-do verteilt die Figuren über und unter die Dachlinie, sodass sich jede Arbeit auf einen Blick lesen lässt.",
  "danwon-daejanggan": "Zwei Schmiede hämmern abwechselnd auf glühendes Eisen, ein Junge tritt den Blasebalg, und ein Mann schärft eine Sichel am Wetzstein. Die Arme sind in verschiedenen Winkeln gezeichnet, sodass man den Rhythmus der Hämmer fast hören kann — ein kleiner Beweis für Kim Hong-dos Auge.",
  "danwon-hwalssogi": "Eine Bogenschießstunde: Der Lehrer fasst den Arm des Schülers, um dessen Haltung zu berichtigen, ein Mann kneift die Augen zusammen und prüft, ob ein Pfeil gerade ist, ein anderer spannt einen Bogen. Bogenschießen gehörte in Joseon zur Bildung eines Herrn, und dieses Blatt zeigt es als alltägliche Übung statt als Zeremonie.",
  "danwon-jumak": "In einer Schenke am Weg isst ein Reisender aus der Schale in seiner Hand, während die Wirtin mit einem Kind auf dem Rücken Suppe aus dem Topf schöpft; ein anderer Gast kramt in seinem Beutel. Kleine Gesten wie diese machen daraus eine warmherzige Aufzeichnung einer gewöhnlichen Mahlzeit unterwegs im späten Joseon.",
  "danwon-jeomsim": "Bauern sitzen zum Mittagessen im Kreis auf dem Feld. Jeder ist in seine Schale vertieft, eine Frau stillt ihr Kind, und ein Hund wartet auf Reste. Statt eines Hintergrunds baut Kim Hong-do den Raum über die Größe der Figuren und ihrer Schalen auf — ein Kennzeichen seines Albums.",
  "danwon-umulga": "Ein Reisender trinkt hastig aus einem Eimer, den ihm eine Frau am Brunnen reicht; sein Hut ist nach hinten geschoben und das Hemd offen, sodass die anderen Frauen die Gesichter abwenden. Mit nicht mehr als sich kreuzenden Blicken deutet das Bild die Spannung zwischen Männern und Frauen in einer konfuzianischen Gesellschaft an.",
  "danwon-gilssam": "Eine Frau webt am Webstuhl, während die Schwiegermutter mit einem Enkelkind auf dem Rücken von hinten zusieht; darunter zettelt eine andere Frau Garn auf einen Baum. Weberei stand im Zentrum der Frauenarbeit in Joseon, und Kim Hong-do hält den Ablauf in zwei ruhigen, übereinandergesetzten Szenen fest.",
  "danwon-naruteo": "Zwei Fähren, beladen mit Fahrgästen, Bündeln und sogar einem Ochsen, überqueren einen Fluss. Herren mit Rosshaarhüten, Hausierer mit ihren Traglasten und die Fährleute an den Rudern teilen sich dasselbe Deck, sodass das Gewimmel einer Joseon-Fährstelle unverfälscht herüberkommt. Das Wasser besteht nur aus wenigen Strichen, was den Blick bei den Menschen hält.",
  "jeongseon-inwang": "Jeong Seons Hauptwerk und ein Nationalschatz, gemalt im Sommer 1751, als über dem Inwang-Berg in Seoul der Regen aufklarte. Schichten dichter Tusche bauen die Granitgipfel auf, Dunst hängt in den Tälern, und ein paar Häuser sitzen klein am Fuß des Bergs. Jeong war sechsundsiebzig und malte es der Überlieferung nach, während sein lebenslanger Freund Yi Byeong-yeon krank daniederlag. 2021 kam es an das Nationalmuseum von Korea.",
  "jeongseon-geumgang": "Ein Nationalschatz von 1734, in dem Jeong Seon die zwölftausend Gipfel des Geumgang-Bergs in einer Vogelschau versammelt. Die zerklüfteten Granitgipfel rechts sind mit scharfen Senkrechten gezeichnet, die Erdhügel links mit weichen Punkten, und beide Hälften schwingen zusammen wie Yin und Yang. Es gilt als Höhepunkt der „Wahren-Ansicht“-Landschaft: wirkliche Natur, vom Auge des Malers neu zusammengesetzt.",
  "hyewon-ssanggeom": "Zwei Tänzerinnen stehen sich mit je einem Schwert in jeder Hand gegenüber, ihre roten und blauen Röcke schwingen in der Drehung auf. Adlige oben und Musiker unten bilden einen Ring, der zur Bühne wird. Von den dreißig Blättern in Shin Yun-boks Album ist dies das mit der kühnsten Farbe und Bewegung.",
  "hyewon-wolha": "Unter einer schmalen Mondsichel treffen sich an einer Mauerecke eine Frau mit einem Umhang über dem Kopf und ein Mann mit einer Laterne. Die Inschrift auf der Mauer gibt dem Bild seinen Sinn: „Der Mond sinkt, die Nacht ist tief, und was diese beiden fühlen, wissen nur sie selbst.“ Es ist Shin Yun-boks berühmtestes Bild der Liebe im nächtlichen Joseon.",
  "hyewon-yeonso": "Junge Adlige reiten zum Frühlingsausflug aus, Gisaeng sitzen auf ihren Pferden, Diener führen die Zügel und tragen die Hüte ihrer Herren, am Hang blühen Azaleen. Shin Yun-bok malt Jünglinge, die das Vergnügen über den Anstand stellen, mit seiner charakteristisch feinen Linie und zarten Farbe.",
  "hyewon-juyu": "Adlige und Gisaeng genießen eine Bootspartie auf einem klaren Fluss: Am Bug spielt ein Junge Flöte, eine Frau lässt die Hand durchs Wasser gleiten, und der Bootsmann rudert, mit einer Felswand am anderen Ufer als Hintergrund. Die Inschrift — „Der Klang der Abendflöte zerstreut sich über den Wellen“ — gibt die Stimmung vor.",
  "hyewon-jusa": "In der Küche einer Schenke wärmt die Wirtin Wein und schenkt ihn in Schalen, während Beamte mit Hüten und roten Röcken im Stehen trinken. Töpfe und Gerät, der Baum im Hof und die verschiedenen Mienen jeder Figur sind sorgfältig gezeichnet und ergeben einen lebendigen Bericht über einen Tag in einem Wirtshaus des späten Joseon.",
  "hyewon-sangchun": "An einem Frühlingstag mit blühenden Azaleen breiten Herren Matten in einem hinteren Garten aus und genießen Musik mit Gisaeng und Musikern. Eine Geomungo und eine Haegeum erklingen, ein Adliger hält eine lange Pfeife, ein Diener trägt ein Tablett mit Wein herein, und Felsen und blühende Bäume dahinter geben dem Garten seine Tiefe.",
  "hyewon-cheonggeum": "An einem Lotusteich lauschen drei Adlige in Gesellschaft von Gisaeng der Geomungo: Der eine neigt sich der Musik zu, der zweite umfängt eine Frau, der dritte schaut mit seiner Pfeife zu. Shin Yun-bok malte die privaten Vergnügungen hinter der Förmlichkeit des Adels ganz ohne Zögern.",
  "geungjae-pajeok": "Eine Katze schießt mit einem Küken im Maul davon, die Henne setzt mit ausgebreiteten Flügeln nach, und der Mann, der auf der Veranda eine Matte flocht, stürzt mit der Pfeife hinterher und verliert dabei mitten in der Luft seinen Hut, während seine Frau hinter ihm aufschreit. Kim Deuk-sin fängt den Augenblick ein, in dem ein stiller Hofnachmittag zerbirst — mit dem Timing eines Comics.",
  "chaekgeori-yitaekgyun": "Ein zehnteiliger Stellschirm mit Büchern, Schreibgerät, Keramik, Blumen und Früchten auf Regalen. Das Chaekgeori-Genre blühte unter König Jeongjo, der die Gelehrsamkeit förderte, und es übernahm westliche Perspektive und Schattierung, sodass die Regale aus der Seide hervorzutreten scheinen. Yi Taek-gyun signierte seine Arbeiten, indem er seinen Namen auf einem gemalten Siegel versteckte — hier kannst du danach suchen.",
  "anjungsik-seongjae": "Der Titel — „Der Klang ist unter den Bäumen“ — stammt aus Ouyang Xius chinesischer Ode über die Klänge des Herbstes: Ein Gelehrter hört den Nachtwind und fragt seinen Dienerjungen, was das sei. An Jung-sik macht den Klang mit rauen, sich biegenden Pinselzügen für die vom Wind bewegten Bäume sichtbar. Er gehörte zu den letzten Meistern der überlieferten Joseon-Manier und bildete die erste Generation moderner koreanischer Maler aus.",
  "minhwa-tiger-magpie": "Ein Volksbild mit einer Elster auf einem Kiefernzweig und einem großäugigen Tiger darunter. Dem Tiger schrieb man zu, Böses abzuwehren, der Elster, gute Nachrichten zu bringen, weshalb solche Bilder zum Neujahrsfest an die Tore geklebt wurden. Der Ausdruck des Tigers, eher tollpatschig als furchterregend, ist der Humor, der für koreanische Minhwa typisch ist.",
  "jojiun-crane-pine": "Ein einzelner Kranich steht still auf dem Ast einer Kiefer. Jo Ji-un, ein Maler des 17. Jahrhunderts, erbte von seinem Vater Jo Sok die Gabe für Vögel und gab sie in zurückhaltender Tusche wieder. Kiefer und Kranich sind beide Sinnbilder langen Lebens, weshalb solche Bilder als Wunsch für Gesundheit und hohes Alter geschätzt wurden.",
  "hwajodo-screen": "Ein zehnteiliger Stellschirm, der auf jedem Feld andere Blumen und Vögel paart: Pfingstrose mit Pfau, Pflaume mit Elster, Lotus mit Ente — jede Paarung nach Jahreszeit und Bedeutung gewählt, um Wohlstand, Eintracht und viele Kinder zu wünschen. Die helle Palette der volkstümlichen Blumen-und-Vogel-Malerei des späten Joseon füllt den ganzen Schirm.",
  "irworobongdo": "Sonne und Mond, fünf Gipfel, zwei Wasserfälle, Kiefern und Wellen in strenger Symmetrie gemalt. Wo immer der König von Joseon saß, stand dieser Schirm hinter dem Thron, und es hieß, das Bild sei erst vollständig, wenn der König davor Platz nahm. Sein geordnetes Muster aus tiefem Blaugrün, Rot und weißer Gischt war ein Sinnbild königlicher Macht.",
  "night-watch": "Ein Gruppenbildnis der Amsterdamer Bürgerwehr unter Hauptmann Frans Banninck Cocq, amtlich „Die Kompanie des Hauptmanns Banninck Cocq“. Statt einer Reihe stehender Männer zeigt Rembrandt die Kompanie im Aufbruch und nutzt Licht und Schatten für die Dramatik; nachgedunkelter Firnis ließ das Bild später als Nachtszene erscheinen, daher der Beiname. Die Leinwand ist über vier Meter breit und hängt im Herzen des Rijksmuseum.",
  "las-meninas": "Die Infantin Margarita mit ihren Hofdamen, Zwergen, einem Hund und dem Maler selbst an der Staffelei, alle in einem Raum des spanischen Hofes. König und Königin erscheinen in einem Spiegel an der Rückwand, sodass der Betrachter an der Stelle des Königspaares zu stehen scheint. Das endlos rätselhafte Spiel darum, wer wen ansieht, hat ihm den Namen „die Theologie der Malerei“ eingetragen.",
  "arnolfini": "Ein Doppelbildnis eines Brügger Kaufmanns und seiner Frau und eines der frühesten Meisterwerke der Ölmalerei. Ein Konvexspiegel an der Rückwand gibt den ganzen Raum und zwei Besucher wieder, und darüber schrieb van Eyck: „Jan van Eyck war hier, 1434.“ Die einzelne Kerze im Leuchter, die Orangen am Fenster und das Hündchen zu ihren Füßen zeigen, wie weit Ölfarbe in der Beschreibung der Welt gehen konnte.",
  "tower-babel": "Bruegel stellte sich den biblischen Turm, der Gottes Zorn erregte, als kolossalen spiralförmigen Bau nach dem Vorbild des Kolosseums vor. Links unten empfängt König Nimrod die Verbeugungen der Steinmetze, während Hunderte winziger Arbeiter überall am Bauwerk mit Kränen und Gerüsten schuften. Je genauer man hinsieht, desto mehr Menschen findet man — ein perfektes Motiv für ein Puzzle.",
  "garden-delights": "Ein Triptychon mit dem Garten Eden links, einem Lustgarten in der Mitte, in dem nackte Gestalten zwischen riesigen Früchten und Vögeln spielen, und einer grotesken Hölle rechts. Wovor Bosch warnen wollte, wird seit fünf Jahrhunderten diskutiert, und die erfundenen Wesen und Episoden, die jeden Zentimeter füllen, wirken bis heute surreal.",
  "liberty": "Zum Gedenken an die Julirevolution von 1830 gemalt: Die Freiheit schreitet mit der Trikolore über eine Barrikade und führt Bürger aller Stände an — einen Bürgerlichen mit Zylinder, einen Jungen mit Pistolen, einen Arbeiter. Durch den Rauch ragen die Türme von Notre-Dame. Delacroix schrieb, wenn er schon nicht für sein Land gekämpft habe, so wolle er wenigstens für es malen.",
  "wanderer": "Ein Mann auf einem Felsgipfel, von hinten gesehen, blickt über ein in Nebel ertrinkendes Gebirge. Weil sein Gesicht verborgen ist, nehmen wir seinen Platz ein, und die Einsamkeit und Ehrfurcht vor der weiten Natur werden zu unseren eigenen. Das Sinnbild der deutschen Romantik schlechthin, unzählige Male auf Buchumschlägen und Plakaten zitiert.",
  "whistler-mother": "Whistler nannte dieses Bildnis seiner Mutter ein „Arrangement in Grau und Schwarz“ und erklärte damit, die Harmonie von Farbe und Form sei wichtiger als die dargestellte Person. Das schwarze Profil, die graue Wand und die Rechtecke von Rahmen und Vorhang ergeben eine karge Komposition, in der nur Gesicht und Spitze ein weiches Licht auffangen. Es gilt oft als das berühmteste amerikanische Gemälde außerhalb Amerikas.",
  "swing": "Eine junge Frau im rosa Kleid schwingt hoch und schleudert ihren Schuh fort, während ein im Gebüsch versteckter junger Mann ihr unter den Rock blickt und ein älterer Ehemann von hinten die Seile zieht. Rokoko-Übermut, schäumendes Laub und der Glanz von Seide — alles ist da in Fragonards berühmtestem Bild.",
  "ophelia": "Die wahnsinnige Ophelia aus Hamlet treibt, Blumen verstreuend, einen Bach hinab. Millais verbrachte fünf Monate am Ufer des Flüsschens Hogsmill, um jede Pflanze und Blüte zu malen, und ließ danach sein Modell Elizabeth Siddal in London in einer Badewanne liegen. Der präraffaelitische Eifer für genaue Naturbeobachtung trifft auf eine der traurigsten Szenen Shakespeares.",
  "shalott": "Nach Tennysons Gedicht: Die verfluchte Lady verlässt ihren Turm und treibt im Boot Camelot entgegen. Zwei der drei Kerzen im Bug sind schon erloschen, und der von ihr gewebte Wandteppich hängt über den Bootsrand. Waterhouse malte das Motiv dreimal; diese erste Fassung ist die beliebteste.",
  "sunflowers": "Eine der Sonnenblumenleinwände, die van Gogh in Arles malte, um das Zimmer zu schmücken, das er für Gauguin herrichtete — ein kühner Versuch, Gelb auf Gelb auf Gelb. Voll erblühte Blumen und schon samende Köpfe teilen sich dieselbe Vase, sodass ein ganzer Lebenslauf in einem Krug steckt. Es ist das meistreproduzierte Bild der National Gallery in London.",
  "cafe-terrace": "Die Terrasse eines Cafés an der Place du Forum in Arles, nachts gemalt. Van Gogh war stolz darauf, die Dunkelheit ohne einen einzigen Strich Schwarz wiedergegeben zu haben — allein mit dem Gelb des Gaslichts gegen den tiefblauen Himmel —, und die Sterne darüber sind die ersten, die er je malte. Das Café steht noch heute an derselben Stelle.",
  "irises": "In der ersten Woche von van Goghs Aufenthalt in der Heilanstalt von Saint-Rémy nach den Schwertlilien in deren Garten gemalt. Jedes violette Blatt ist dunkelblau umrissen, und eine einzelne weiße Iris am linken Rand lässt die Komposition atmen. Der Aufbau verdankt japanischen Holzschnitten viel; berühmt wurde das Bild, als es 1987 einen Auktionsrekord aufstellte.",
  "rhone": "Nachts am Ufer der Rhône in Arles gemalt: Der Große Wagen hängt am Himmel, und die Gaslichter der Stadt ziehen lange Spiegelungen über das Wasser. Van Gogh schrieb seinem Bruder Theo, die Nacht sei weit farbiger als der Tag. Ein Liebespaar im Vordergrund gibt der weiten dunklen Landschaft menschliche Wärme.",
  "wheatfield-crows": "Wenige Wochen vor van Goghs Tod in Auvers gemalt. Unter einem Gewitterhimmel teilt sich ein gelbes Weizenfeld in drei Wege, und ein Krähenschwarm steigt auf. Er schrieb, er habe in diesen Feldern Traurigkeit und äußerste Einsamkeit ausdrücken wollen — und zugleich die Gesundheit und Kraft des Landes.",
  "rousseau-dream": "Rousseaus letztes großes Bild: Eine Frau auf einem roten Sofa mitten im Dschungel blickt auf Löwen, einen Elefanten und einen Schlangenbeschwörer. Rousseau verließ Paris nie und baute seine Dschungel aus dem Botanischen Garten und Bilderbüchern; das Sofa, erklärte er, sei im Traum der Frau einfach in den Dschungel getragen worden.",
  "adele": "Die Frau eines Wiener Bankiers, in Gold- und Silberblatt gehüllt — der Gipfel von Klimts goldener Periode. Nur Gesicht und Hände sind naturalistisch gemalt; Kleid und Grund lösen sich in Augen, Spiralen und Dreiecke auf, die an byzantinische Mosaiken erinnern. Von den Nationalsozialisten geraubt und 2006 an die Familie zurückgegeben, wurde seine Geschichte zum Film „Die Frau in Gold“.",
  "boating-party": "Renoirs Freunde verweilen nach dem Essen auf der Terrasse eines Restaurants in Chatou an der Seine. Die Frau mit dem Hündchen ist Aline Charigot, später seine Ehefrau, und rechts unten sitzt der Maler Caillebotte. Flaschen, Früchte, Strohhüte und die gestreifte Markise fangen alle das Licht ein — oft das glücklichste Bild des Impressionismus genannt.",
  "folies": "Manets letztes großes Bild zeigt Suzon, eine Schankkellnerin im Pariser Varieté Folies-Bergère. Ihre Spiegelung und der Gast im Spiegel dahinter stehen nicht dort, wo sie stehen müssten, und ob die Verschiebung Absicht ist, wird bis heute diskutiert. Flaschen und Orangen auf dem Marmor und das Funkeln der Lüster vermitteln den Glanz der Nacht.",
  "dance-class": "In einem Probensaal der Pariser Oper stützt sich der Ballettmeister Jules Perrot auf seinen Stock und sieht den Mädchen zu. Degas zog die Hinterbühnenwahrheit des Wartens, der Langeweile und eines gekratzten Rückens dem vollkommenen Augenblick auf der Bühne vor. Der schräge Blickwinkel, der Spiegel und das Plakat an der Wand geben dem Raum seine Tiefe.",
  "sipjangsaengdo": "Ein Stellschirm, der zehn Sinnbilder langen Lebens in einer Landschaft versammelt: Sonne, Berge, Wasser, Felsen, Wolken, Kiefern, das Kraut der Unsterblichkeit, Schildkröten, Kraniche und Hirsche. Solche Schirme standen im Palast, um dem König langes Leben zu wünschen oder das neue Jahr zu begrüßen, und die blaugrünen Hügel mit roter Sonne und weißen Kranichen ergeben eines der farbenreichsten Motive der Joseon-Hofmalerei.",
  "parasol": "Auf einem Hügel bei Argenteuil gemalt, mit dem Blick hinauf zu Monets Frau Camille und ihrem Sohn Jean. Der vom Wind bewegte Schleier und das Gras und das grüne Licht, das sich unter dem Sonnenschirm auf ihrem Gesicht spiegelt, entstanden in wenigen Stunden schnellen Pinselns; Monet verstand es eher als Freilichtstudie denn als Bildnis. Die Helligkeit und Schnelligkeit des Impressionismus stecken hier ganz drin.",
  "hay-wain": "Ein Wagen durchquert eine Furt des Flusses Stour in Suffolk — die berühmteste aller englischen Landschaften. Constable malte den Fluss seiner Kindheit sein Leben lang, und das Häuschen links steht noch heute. Die wahrhaftigen Wolken und Spiegelungen verblüfften französische Maler, als das Bild in Paris gezeigt wurde, und halfen den Impressionismus vorzubereiten.",
  "temeraire": "Die Temeraire, eine Heldin von Trafalgar, wird von einem kleinen Dampfschlepper zum Abwracken geschleppt. Das bleiche, gespenstische Segelschiff, der schwarzen Rauch speiende Schlepper und der lodernde Sonnenuntergang betrauern gemeinsam das Ende der Segelzeit. Zum Lieblingsgemälde der Briten gewählt, erscheint es heute auf der Zwanzig-Pfund-Note.",
  "primavera": "Venus steht in der Mitte eines Orangenhains; rechts ergreift der Westwind eine Nymphe, die sich in Flora, die Blumengöttin, verwandelt, während links die drei Grazien tanzen und Merkur die Wolken vertreibt. Auf der Wiese wachsen etwa fünfhundert bestimmbare Pflanzen. Für die Medici gemalt, ist es die Renaissance-Mythologie in ihrer reinsten Form.",
  "school-athens": "Ein Fresko an der Wand der päpstlichen Bibliothek im Vatikan, das die Philosophen des antiken Griechenland unter einem großen Gewölbe versammelt. In der Mitte weist Platon zum Himmel und Aristoteles zur Erde, um sie herum Pythagoras, Euklid und Diogenes, und Raffael schmuggelte sein eigenes Gesicht in die rechte Ecke. Es ist der Renaissance-Traum von der Vernunft in einem einzigen Bild.",
  "last-supper": "An die Wand des Refektoriums eines Mailänder Klosters gemalt, hält es den Augenblick nach „Einer von euch wird mich verraten“ fest: Die zwölf Apostel reagieren in Dreiergruppen — erschrocken, fragend, sich verwahrend. Leonardo verwendete statt echten Freskos eine Versuchstechnik, weshalb die Malerei fast sofort abzublättern begann; Jahrhunderte der Restaurierung haben ihr den heutigen Zustand gegeben.",
  "bathers-asnieres": "Junge Arbeiter kühlen sich am Seineufer bei Asnières ab, gegenüber die Fabrikschlote, die Figuren so still wie antike Skulpturen. Seurats erste große Leinwand, mit vierundzwanzig gemalt, zeigt seine Versuche, Farben nebeneinanderzusetzen — kurz bevor der eigentliche Pointillismus entstand.",
  "seurat-circus": "Im Cirque Fernando in Paris steht eine Kunstreiterin auf einem Schimmel, während ein Clown durch die Luft fliegt und das Publikum nach Kartenpreis gestaffelt sitzt. Seurat baute das Bild aus Punkten in Gelb, Orange und Blau und drückte Heiterkeit mit geschwungenen Linien aus; es war sein letztes Werk und bei seinem Tod während der Ausstellung noch unvollendet.",
  "napoleon-alps": "Es erinnert an Napoleons Überquerung des Großen St. Bernhard nach Italien im Jahr 1800. Tatsächlich ritt er ein Maultier, bat aber darum, „ruhig auf einem feurigen Pferd“ dargestellt zu werden, und David meißelte BONAPARTE neben die Namen Hannibals und Karls des Großen in die Felsen. Fünf Fassungen entstanden; diese gehört dem Belvedere in Wien.",
  "view-delft": "Vermeers Heimatstadt vom anderen Ufer des Hafens gesehen — eine von nur zwei Stadtansichten, die er malte. Der Schatten einer Wolke zieht über die Dächer, Sonnenlicht fällt allein auf den Turm der Neuen Kirche rechts, und Boote und Mauern zittern in ihren Spiegelungen. Proust nannte es das schönste Gemälde der Welt.",
  "art-of-painting": "Hinter einem zurückgezogenen Vorhang malt ein Maler mit dem Rücken zu uns ein lorbeerbekröntes Modell: Sie ist Klio, die Muse der Geschichte, und die Karte an der Wand zeigt die siebzehn Provinzen der alten Niederlande. Vermeer behielt dieses Bild trotz seiner Schulden bis zu seinem Tod, und man liest es als seine Erklärung über den Ruhm, den die Malerei in der Geschichte erringen kann.",
  "little-street": "Zwei Backsteinhäuser in Delft und die Gasse dazwischen. Eine Frau näht in einem Türrahmen, eine andere putzt im Durchgang, Kinder spielen auf dem Pflaster, und jeder Riss im Ziegel und jeder Fleck Kalkanstrich ist liebevoll festgehalten. Neuere Forschungen haben das Haus als Wohnung von Vermeers Tante bestimmt.",
  "harvesters": "Hochsommer: Einige Bauern schneiden und binden den Weizen, während andere im Schatten eines Birnbaums Brot und Brei essen und einer ausgestreckt schläft. Eines von Bruegels sechs Jahreszeitenbildern und eines der ersten Werke der westlichen Kunst, in denen Arbeit und Landschaft selbst zum Thema werden statt Religion oder Mythos.",
  "peasant-wedding": "Ein ländliches Hochzeitsmahl in einer Scheune. Die Braut sitzt sittsam unter einem grünen Tuch, Schüsseln mit Brei werden auf einer ausgehängten Tür hereingetragen, und ein Dudelsackpfeifer kann die Augen nicht vom Essen lassen. Ein Kind vorn leckt sich die Finger, und der Mann ganz rechts im Gespräch mit einem Mönch gilt als Bruegel selbst.",
  "goya-parasol": "Ein junger Mann beschattet eine junge Frau mit einem grünen Sonnenschirm, während sie mit einem Schoßhündchen auf dem Knie zu uns herausblickt. Als Entwurf für einen königlichen Wandteppich gemalt, hat es leuchtende Farben und einen einfachen Aufbau und zeigt die Rokoko-Heiterkeit des jungen Goya von ihrer besten Seite.",
  "flaming-june": "Eine Frau in einem durchscheinenden orangefarbenen Kleid schläft zusammengerollt vor einem glitzernden Mittelmeer; der Oleander über ihr ist giftig und deutet die Verwandtschaft von Schlaf und Tod an. Nach der viktorianischen Zeit vergessen und in den 1960er Jahren kaum teurer als sein Rahmen verkauft, ist es heute der Stolz des Museo de Arte de Ponce in Puerto Rico.",
  "heliogabalus": "Der römische Kaiser Heliogabal soll ein Dach aus Rosenblättern auf seine Gäste haben herabregnen lassen, bis sie erstickten. Alma-Tadema ließ sich den Winter über wöchentlich Rosen von der Riviera schicken, um jedes Blütenblatt zu malen, und polierter Marmor und Seide waren seine Spezialität. Grausamkeit, in Prunk verborgen — ein Schlüsselwerk der viktorianischen Zeit.",
  "vertumnus": "Der römisch-deutsche Kaiser Rudolf II. als Vertumnus, Gott der Jahreszeiten, das ganze Gesicht aus Früchten, Gemüse und Blumen zusammengesetzt: eine Birne als Nase, Äpfel als Wangen, Weizenähren als Brauen. Der Kaiser war entzückt und verstand es als Sinnbild von Fülle und Eintracht, nicht als Beleidigung. Die Surrealisten entdeckten es vier Jahrhunderte später wieder.",
  "storm-galilee": "Rembrandts einziges Seestück: Im Sturm ringen die Jünger mit dem Segel, erbrechen sich und beten, während Christus im Heck erwacht. Der Mann, der ein Tau umklammert und zu uns herausblickt, ist Rembrandt selbst. 1990 aus dem Gardner Museum in Boston gestohlen und nie wiedergefunden, hängt sein leerer Rahmen bis heute an der Wand.",
  "basket-fruit": "Ein Korb mit einem wurmstichigen Apfel, welkenden Blättern und einer vertrockneten Rebe, genau so gemalt, wie sie waren, steht kippelig über der Tischkante. Mit leerem Hintergrund und den Früchten auf Augenhöhe gilt es als das erste eigenständige Stillleben der westlichen Kunst; Caravaggio sagte, ein Blumenbild verdiene ebenso viel Sorgfalt wie ein Figurenbild.",
  "bosschaert-bouquet": "Tulpen, Rosen, Schwertlilien und Nelken teilen sich eine Vase, obwohl sie nie zur selben Zeit blühen. Bosschaert setzte aus Studien jeder einzelnen Blume einen idealen Strauß zusammen und malte die Schmetterlinge und Tautropfen auf den Blättern wie Juwelen. Es steht am Anfang der niederländischen Blumenmalerei, kurz vor der Tulpenmanie.",
  "ninth-wave": "Überlebende eines nächtlichen Sturms klammern sich im Morgengrauen an ein Stück Mast, während die „neunte Welle“, die Seeleute für die größte hielten, auf sie zurollt. Doch die aufgehende Sonne färbt Himmel und Wasser golden und violett, und das Bild spricht eher von Hoffnung als von Verzweiflung. Es ist das Meisterwerk Aiwasowskis, des größten russischen Marinemalers.",
  "sorolla-seashore": "Sorollas Frau Clotilde und Tochter María gehen in weißen Kleidern gegen die Brise am Strand von Valencia. Die Falten des sonnenbeschienenen Stoffs, der Sonnenschirm und das Hutband sind in breiten Strichen angelegt, sodass das Licht des Mittelmeers selbst anzukommen scheint. Es ist das beliebteste Bild des „Malers des Lichts“.",
  "cassatt-boating": "Vor Antibes zieht ein Bootsmann am Ruder, während ein Kind auf dem Schoß seiner Mutter ihn beobachtet. Der starke Kontrast von gelbem Boot und blauem Meer und die Schrägen von Segel und Ruder stammen aus japanischen Holzschnitten. Cassatt malte ihr Leben lang Mütter und Kinder, und dies ist die kühnste Komposition darunter.",
  "breezing-up": "Vor dem Hafen von Gloucester jagt ein Fischer mit drei Jungen in einem kleinen Catboat vor dem Wind dahin. Der Junge am Ruder blickt zum Horizont, und das Boot legt sich über, während es durchs Wasser schneidet. Auf der Weltausstellung von 1876 gezeigt, wurde es als Bild des Optimismus einer jungen Nation aufgenommen.",
  "sierra-nevada": "Licht, das durch Wolken strömt, ein Wasserfall, ein spiegelglatter See und Rehe am Ufer verwandeln die kalifornischen Berge in ein Paradies. Bierstadt fügte Ansichten mehrerer Orte zu einer idealen Szene zusammen, und für die Europäer, die es sahen, wurde der amerikanische Westen zu einer majestätischen neuen Welt. Ein Schlüsselwerk der Hudson River School.",
  "oxbow": "Die Flussschleife des Connecticut, vom Mount Holyoke in Massachusetts gesehen. Links vom Sturm gepeitschte Wildnis, rechts sonnenbeschienenes Ackerland: amerikanische Natur und Zivilisation nebeneinandergestellt. Cole malte auf die Felsen darunter ein winziges Selbstbildnis, das zu uns zurückblickt.",
  "canaletto-grand-canal": "An der Mündung des Canal Grande erhebt sich die Kuppel der Salute über dem Wasser, während Gondeln und Lastkähne vorüberziehen. Canaletto verkaufte solche Ansichten an englische Adlige auf der Grand Tour und benutzte eine Camera obscura, um die Proportionen der Gebäude richtig hinzubekommen. Das Venedig von vor dreihundert Jahren sieht fast genauso aus wie heute.",
  "montmartre-night": "Die einzige Nachtszene unter vierzehn Ansichten des Boulevard Montmartre, die Pissarro über Jahreszeiten und Tageszeiten hinweg aus einem Pariser Hotelfenster malte. Gaslaternen und Schaufenster verschmieren auf der nassen Straße, und Kutschen und Passanten sind auf wenige Tupfer verkürzt. Eine seltene impressionistische Stadtnacht, zu seinen Lebzeiten nie ausgestellt.",
  "plum-garden": "Aus „Hundert berühmte Ansichten von Edo“: Der gefeierte alte Pflaumenbaum von Kameido ist kühn von seinem dicken Stamm im Vordergrund durchschnitten, die Blütenbetrachter dahinter sind klein. Roter Himmel vor grünem Grund ergibt einen aufsehenerregenden Kontrast. Van Gogh kopierte dieses Blatt in Öl.",
  "kajikazawa": "Aus den „Sechsunddreißig Ansichten des Berges Fuji“: Ein Fischer auf einer Felsnase wirft sein Netz in die Stromschnellen, neben ihm sitzt ein Junge. Das Dreieck aus Fischer und Leinen ist so angelegt, dass es das Dreieck des Fuji im Dunst dahinter aufnimmt — ein Meisterstück der Bildanlage. Frühe Abzüge wie dieser wurden ganz in Blauabstufungen gedruckt.",
  "audubon-flamingo": "Das berühmteste der 435 Blätter aus Audubons „Die Vögel Amerikas“. Damit der Vogel in Lebensgröße bleibt, beugt der hohe Flamingo den Hals, um auf die Seite zu passen, dahinter kleinere Flamingos und Details von Schnabel und Fuß. Nach Vögeln entstanden, die er auf den Florida Keys beobachtete, wurde es in London gestochen und von Hand koloriert.",
  "larsson-breakfast": "Die Familie Larsson beim Frühstück unter einer Birke im Garten ihres Hauses in Sundborn in Schweden. Eines der Aquarelle aus „Ein Heim“, Larssons Folge über sein eigenes Haus und seine Kinder, deren helle Farben, schlichte Möbel und sonniger Garten zur Vorlage skandinavischer Innenräume wurden.",
  "poppy-field": "Mohnblumen streuen Rot über ein Feld bei Argenteuil, mit einer Frau unter dem Sonnenschirm und einem Kind, die zweimal erscheinen — oben und unten am Hang. Es sind Monets Frau Camille und Sohn Jean, und die beiden Paare geben den Rhythmus des Hinabgehens. Gezeigt wurde es auf der ersten Impressionistenausstellung 1874.",
  "bougival": "Ein Paar tanzt in einem Gartenlokal in Bougival vor Paris. Die Frau mit der roten Haube ist die Malerin Suzanne Valadon, und der Strohhut des Mannes und ihre Röcke verwischen in der Bewegung. Ein fallengelassener Strauß und Zigarettenstummel am Boden erzählen von der Ausgelassenheit des Tages.",
  "vision-sermon": "Bretonische Frauen sehen nach einer Predigt die Vision, wie Jakob mit dem Engel ringt. Ein Baumstamm trennt die wirklichen Frauen von der Vision, und der Boden ist flach zinnoberrot gemalt, unter Verzicht auf Perspektive und Naturfarbe. Es markiert Gauguins Wende vom Impressionismus zum Symbolismus; er bot es der Dorfkirche an, die es ablehnte.",
  "sainte-victoire": "Eine der Dutzenden Ansichten, die Cézanne von dem Berg bei seinem Geburtsort Aix-en-Provence malte, hier über die orangefarbenen Felsen eines aufgelassenen Steinbruchs gesehen. Felsen, Bäume und Berg sind aus Farbflächen aufgebaut, die aus der Leinwand nach vorn zu drängen scheinen, und dieser feste Bau wurde zu einem Ausgangspunkt des Kubismus.",
  "dejeuner": "Eine nackte Frau sitzt neben zwei vollständig bekleideten Männern und blickt gelassen zu uns heraus. Vom Salon von 1863 abgelehnt und im „Salon des Refusés“ gehängt, erregte es Anstoß, weil der Akt eine moderne Frau war und keine Göttin. Es entlehnt seinen Aufbau Raffael und Giorgione, überträgt ihn in die Gegenwart und kündigt so den Beginn der modernen Malerei an.",
  "girl-reading": "Ein Mädchen am Fenster liest einen Brief, während sich ihr Gesicht schwach in der Scheibe spiegelt. Die lange leere Wand hinter ihr gab bei einer Restaurierung 2021 ein Bild des Amor frei und bewies, dass Vermeer uns von Anfang an sagen wollte: Dies ist ein Liebesbrief. Eine Obstschale und ein Vorhang davor rahmen die Szene wie eine Bühne.",
  "isle-dead": "Eine von Zypressen bekrönte Felseninsel erhebt sich aus stillem Wasser, während sich ein Boot mit einer weiß gewandeten Gestalt und einem Sarg nähert. Böcklin malte die Insel nach einem Auftrag für „ein Bild zum Träumen“ fünfmal, und im Deutschland des frühen 20. Jahrhunderts hing ein Druck davon in fast jedem Haus. Rachmaninow schrieb nach dem Anblick eine sinfonische Dichtung.",
  "hylas": "Aus der griechischen Mythologie: Der Jüngling Hylas, der Wasser holen will, wird von den Nymphen des Teichs ergriffen und hinabgezogen. Dunkles, mit Seerosen bestreutes Wasser, sieben Nymphen mit denselben blassen Gesichtern und kastanienbraunem Haar und Hylas' zögernde Geste erzeugen eine wie verzaubert wirkende Stimmung. Es ist Waterhouse' bekanntestes Bild.",
  "munch-sun": "Die Mittelleinwand der Wandbilder, die Munch für die Aula der Universität Oslo malte: Die Sonne geht über dem Meer auf und überflutet das Bild mit Strahlen. Frei von der Angst des „Schreis“ machte Munch die norwegische Küste am Morgen auf einer fast acht Meter breiten Leinwand zum Sinnbild von Lebenskraft und Hoffnung.",
  "ejiri": "Aus den „Sechsunddreißig Ansichten des Berges Fuji“: Eine plötzliche Bö wirbelt Hüte und Papierbögen der Reisenden in den Himmel und biegt die Bäume. Menschen ducken sich und halten ihre Kleider fest, während allein der Fuji in der Ferne unbewegt dasteht. Hokusais Witz blitzt darin auf, den unsichtbaren Wind über verstreutes Papier zu malen.",
  "carnation-lily": "In der Dämmerung eines Gartens zünden zwei Mädchen in Weiß Papierlaternen an. Weil das Abendlicht nur wenige Minuten stimmte, malte Sargent zwei Sommer lang jeden Abend ein paar Minuten. Der Titel stammt aus einem damals bekannten Lied, und das Bild begründete seinen Ruf in England.",
  "blue-armchair": "Ein kleines Mädchen fläzt gelangweilt in einem riesigen blauen Sessel, während neben ihr ein Hündchen im Sessel schläft. Sie war die Tochter eines Freundes von Degas, der einen Teil des Hintergrunds selbst überarbeitete. Die Kühnheit, statt eines artigen Bildnisses die Langeweile eines Kindes zu zeigen, machte es zu einem von Cassatts Hauptwerken.",
  "water-lily-pond": "Die japanische Brücke, die Monet in seinem Garten in Giverny baute, und der Seerosenteich darunter. Im Sommer 1899 malte er die Brücke über ein Dutzend Mal; hier füllen Weiden und Seerosen die Leinwand so vollständig, dass kein Himmel zu sehen ist. Es ist der Ausgangspunkt der Seerosenserie, die ihn dreißig Jahre beschäftigen sollte.",
  "sainte-adresse": "Auf einer Terrasse über der normannischen Küste sitzt Monets Vater und blickt aufs Meer, Fahnen knattern im Wind, und in der Ferne zieht ein Dampfer vorbei. Die Aufteilung in drei Bänder — Terrasse, Meer und Himmel —, durchkreuzt von den Senkrechten der Fahnenmasten, ist von japanischen Holzschnitten gelernt, und Monet selbst nannte es sein japanisches Bild.",
  "umbrellas": "Schirme überlagern sich wie Wellen in einer verregneten Pariser Straße, vorn ein Mädchen mit einem Reifen und eine junge Frau mit einem Korb. Die rechte Seite entstand 1881 in der weichen impressionistischen Manier, die linke einige Jahre später nach einer Italienreise mit festeren Umrissen — zwei Perioden Renoirs in einem Bild.",
  "night-cafe": "Der nächtliche Innenraum eines Cafés beim Bahnhof in Arles, wo rote Wände, ein grüner Billardtisch und gelbe Lampen aufeinanderprallen. Van Gogh schrieb, er habe mit Rot und Grün „die schrecklichen Leidenschaften der Menschheit“ ausdrücken wollen und einen Ort gemalt, an dem man verrückt werden oder ein Verbrechen begehen könne. Er blieb drei Nächte wach, um es zu malen.",
  "beech-grove": "Ein Buchenwald am Attersee, von Klimt in seinem bevorzugten quadratischen Format gemalt. Gerade Stämme teilen das Bild senkrecht, während das Falllaub wie im Pointillismus eingetupft ist, sodass der ganze Wald als Muster lesbar wird. Berühmt für seine goldenen Figuren, malte Klimt jeden Sommer solche Landschaften.",
  "farm-garden": "Sonnenblumen und Blüten aller Art drängen sich in einem Bauerngarten am Attersee über die ganze Leinwand. Klimt malt das Beet wie einen mit Juwelen bestreuten Teppich und sieht die Natur mit demselben Auge, das er dem Gold seiner Bildnisse zuwandte. Ohne Himmel und Hintergrund, nur Blumen, wird es als Puzzle zu einem Fest der Farbe.",
  "angelus": "In der Dämmerung auf einem Kartoffelfeld halten ein Bauernpaar in der Arbeit inne und beten, während von der fernen Kirche die Abendglocke läutet. Millet sagte, er habe daran gedacht, wie seine Großmutter innehielt und betete, sobald sie die Glocke hörte. Seine demütige Frömmigkeit machte es zu einem der beliebtesten Bilder Frankreichs, und Dalí war so besessen davon, dass er es viele Male neu malte.",
  "laughing-cavalier": "Ein Sechsundzwanzigjähriger, die Hand in die Hüfte gestützt, blickt mit hochgezwirbelten Schnurrbartspitzen lächelnd auf uns herab. Die auf seinen Ärmel gestickten Pfeile, Bienen und Liebesknoten sind Sinnbilder der Liebe, weshalb man es für ein Verlobungsbildnis hält. Der Beiname blieb hängen, obwohl er eher lächelt als lacht, und Hals' lebendiger Pinselstrich passt zum selbstbewussten Ausdruck.",
  "bacchus-ariadne": "Ariadne, von Theseus am Strand zurückgelassen, wird von Bacchus überrascht, der von seinem leopardengezogenen Wagen springt und sich auf den ersten Blick verliebt; das Sternbild am Himmel ist die Krone, die er ihr schenkte, in Sterne verwandelt. Für das Studierzimmer des Herzogs von Ferrara gemalt, leuchtet sein Himmel im kostbaren Blau des Lapislazuli.",
  "creation-adam": "In der Mitte der Sixtinischen Decke streckt Gott den Finger aus, um Adam Leben zu geben. Der kleine Zwischenraum zwischen den beiden Fingern erzeugt die ganze Spannung des Bildes, und der rote Mantel um Gott wurde als Umriss eines menschlichen Gehirns gedeutet. Es ist das Herzstück der Decke, die Michelangelo vier Jahre lang von einem Gerüst aus malte.",
  "rain-steam-speed": "Eine Dampflokomotive rast durch Regen und Dunst über die Maidenhead-Brücke an der Themse auf uns zu. Nur Brücke und Zug behalten ihre Form; alles andere löst sich in einen Wirbel aus Licht und Nässe auf, und auf dem Gleis voraus läuft ein winziger Hase um die Wette. Es gilt als das erste Bild, das die Geschwindigkeit des Industriezeitalters einfing.",
  "san-giorgio": "Während seines Aufenthalts in Venedig im Herbst 1908 malte Monet die Kirche und den Campanile von San Giorgio Maggiore über die Lagune hinweg im Abendlicht. Himmel und Wasser, beide orange und violett gefärbt, gehen ineinander über, sodass die Gebäude nur als Silhouetten bleiben. Es ist das farbstärkste Bild seiner venezianischen Serie.",
  "mucha-zodiac": "Eine Frau im Profil, hinter ihr eine Scheibe mit den zwölf Tierkreiszeichen, die wie ein Heiligenschein leuchtet — Muchas berühmteste Zierplatte. Als Kalender für den Drucker Champenois entworfen, wurde sie bekannt, als die Zeitschrift „La Plume“ sie als Titelbild verwendete. Das sich ringelnde Haar, die Juwelen und das byzantinische Ornament sind Jugendstil in reinster Form.",
  "mucha-job": "Ein Werbeplakat für Job-Zigarettenpapier: eine Frau mit halb geschlossenen Augen, deren Haar sich mit dem Rauch verschlingt, der das Blatt füllt, während sich hinter ihr die Buchstaben JOB als Muster wiederholen. Als es in den Straßen von Paris aushing, rissen die Leute es von den Wänden, um es zu behalten — eine Legende des Jugendstilplakats.",
  "rouen-cathedral": "Eine von über dreißig Leinwänden, die Monet von der Kathedralfassade aus einem gegenüberliegenden Zimmer malte, den Wechseln von Stunde und Wetter folgend. Das Motiv ist nicht der Stein, sondern das Licht, das darüber bricht, und die dick aufgetragene Farbe wird selbst zur Struktur der Mauer. Zwanzig von ihnen 1895 gemeinsam zu zeigen, vollendete seinen Gedanken der Serie.",
  "watering-can": "Ein kleines Mädchen in einem blauen, mit Spitze besetzten Kleid steht mit einer Gießkanne auf einem Gartenweg und blickt zu uns heraus. Blumen und Blätter dahinter lösen sich in Farbtupfer auf, die mit ihrer Gestalt verschmelzen, und das Rot von Schleife und Knöpfen setzt den Akzent. Es ist das hellste und liebenswerteste von Renoirs Kinderbildern.",
  "proverbs": "Über hundert Sprichwörter, als Szenen in einem einzigen Dorf versteckt: Torten auf dem Dach, ein Mann, der mit dem Kopf gegen die Wand rennt, jemand, der Rosen vor die Säue wirft, eine Frau, die ihrem Mann einen blauen Mantel umhängt. Jedes einzelne war eine Redensart der Zeit. Bruegels Komödie der menschlichen Torheit gibt bei jedem Hinsehen eine neue Geschichte her.",
  "magpie": "Eine einzelne Elster sitzt auf einem Gatter in verschneiter Landschaft. Monet malte die Schatten auf dem Schnee blau statt schwarz; die Jury des Salons wies das Bild zurück, doch später sah man darin eine frühe Erklärung des impressionistischen Umgangs mit Licht. Es ist das berühmteste seiner rund 140 Schneebilder.",
  "sisley-snow": "Ein verschneiter Weg im Dorf Louveciennes westlich von Paris, zwischen Gartenmauern gesehen. Eine Frau geht allein mit einem Schirm, und der graue Himmel, die schneebeladenen Dächer und die nassen Mauern vermitteln die Stille des Winters. Sisley malte sein Leben lang nichts als Landschaften, und seine Schneebilder zeigen seine feinsten Farben.",
  "attersee": "Das gekräuselte Wasser des Attersees in Österreich füllt fast die ganze quadratische Leinwand und lässt oben nur einen schmalen Streifen Insel und fernes Ufer. Klimt fasste die Ansicht, als schnitte er sie vom Boot aus mit einem Fernrohr heraus, und tupfte jede Kräuselung mit kurzen Strichen ein, bis das Wasser wie ein Mosaik schimmert.",
  "composition-vii": "Die größte und komplexeste von Kandinskys Abstraktionen, in München am Vorabend des Ersten Weltkriegs gemalt. Nach über dreißig Studien vollendete er sie in dreieinhalb Tagen, und Bilder von Sintflut, Jüngstem Gericht und Auferstehung sind in ihrem Wirbel aus Farbe und Linie aufgelöst. Er verglich das Bild mit einer Sinfonie.",
  "surprised": "In einem vom Blitz erhellten Dschungel duckt sich ein Tiger, bereit, auf seine Beute zu springen. Rousseaus erstes Dschungelbild, mit schrägen Silberstrichen für den Wolkenbruch und Schicht um Schicht verschiedener Grüntöne für das Laub. Kritiker verspotteten es als kindlich, doch dieser unschuldige Dschungel öffnete den Malern des 20. Jahrhunderts eine neue Tür.",
  "hida-bridge": "Aus der Serie „Bemerkenswerte Ansichten von Brücken in verschiedenen Provinzen“: Zwei Reisende mit Lasten überqueren eine über eine tiefe Schlucht gespannte Hängebrücke. Die durchhängende Kurve der Brücke, die Wolken darunter und die gestaffelten Berge dahinter machen die schwindelnde Höhe greifbar, und die unter ihren Füßen fliegenden Vögel setzen den Punkt.",
  "fishing-boats": "Auf einem kurzen Ausflug von Arles ins mittelmeerische Fischerdorf Saintes-Maries-de-la-Mer gemalt. Kleine, bunt bemalte Boote liegen auf dem Sand, und van Gogh schrieb seinem Bruder, die Boote seien „so hübsch wie Blumen“. Rote Masten, blaue Rümpfe und gelber Sand tragen das Licht Südfrankreichs.",
  "regatta": "Weiße Segelboote auf der Seine bei Argenteuil werfen zitternde Spiegelungen, während sie sich zur Regatta bereitmachen. Die gespiegelten Segel und Häuser sind in breiten, kühnen Strichen angelegt, sodass die untere Bildhälfte der oberen antwortet. Es ist eines der beschwingtesten Bilder aus Monets Jahren in Argenteuil.",
  "cradle": "Morisots Schwester Edma betrachtet durch einen durchscheinenden Vorhang ihr schlafendes Kind. Der Blick der Mutter und die Haltung des Kindes verbinden sich entlang einer Diagonale, und der Pinselstrich des durchsichtigen weißen Tuchs ist erstaunlich leicht. Als einziges Werk einer Frau auf der ersten Impressionistenausstellung von 1874 fand es keinen Käufer und blieb in der Familie.",
  "barge-haulers": "Elf Männer stapfen über eine Sandbank der Wolga und ziehen einen Lastkahn am Seil. Repin verbrachte einen Sommer am Fluss, um sie kennenzulernen, und gab jedem ein anderes Gesicht — vom erschöpften Alten bis zum Burschen, der seinen Gurt zurechtrückt. Es kündigte den Beginn des russischen Realismus an.",
  "pine-forest": "Drei Bärenjunge spielen auf einem umgestürzten Baum in einem nebligen Kiefernwald, während die Mutter zusieht. Schischkin malte den Wald und sein Freund Sawizki die Bären, dessen Signatur später entfernt wurde. Auf Schokoladenpapier gedruckt, wurde es zu einem Bild, das jeder Russe kennt.",
  "golden-autumn": "Ein Fluss windet sich zwischen Birken, die in der Herbstsonne golden geworden sind. Lewitan war der Maler der russischen „Stimmungslandschaften“, und die hellen Gelb- und Blautöne hier gehören zu einem seltenen zuversichtlichen Moment seines Lebens. Es ist das Herbstbild der russischen Kunst schlechthin.",
  "korin-irises": "Ein Paar sechsteiliger Stellschirme zu einer Szene aus den Ise-Erzählungen, in der ein Dichter an einem von acht Brücken durchzogenen Schwertliliensumpf Verse dichtet — gemalt ganz ohne Figur, nur Schwertlilien und Brücken. Auf Goldgrund verwendete Kōrin allein Ultramarin und Grün und wiederholte die Blüten wie einen Rhythmus, während die Zickzackbrücke quer hindurchschneidet. Ein Meisterwerk des Rinpa-Stils.",
  "wind-thunder": "An den beiden Enden eines Paars goldener Stellschirme stehen sich der Windgott mit seinem Windsack und der Donnergott mit seinem Trommelkranz auf Wolken gegenüber. Die leer gelassene Mitte erzeugt die Spannung zweier aufeinander zustürmender Götter, und die Wolken sind mit fließender Tusche gemacht. Ein Nationalschatz im Kennin-ji in Kyoto, von späteren Malern immer wieder kopiert.",
  "three-beauties": "Drei gefeierte Schönheiten von Edo — die Teehaustöchter Okita und Ohisa und die Geisha Toyohina —, in Utamaros berühmtestem Blatt zum Dreieck geordnet. Die Gesichter wirken auf den ersten Blick gleich, doch Augen, Nasen und Brauen unterscheiden sich gerade genug, dass Zeitgenossen sie auseinanderhalten konnten. Ein mit Glimmer bestäubter Grund funkelt und hebt die Figuren ab.",
  "koson-crow": "Eine Krähe auf einem schneebeladenen Zweig öffnet den Schnabel zum Krächzen. Ohara Koson schuf im frühen 20. Jahrhundert Blumen-und-Vogel-Blätter vor allem für den Export und war in Europa und Amerika sehr beliebt; hier vermitteln allein der Glanz schwarzer Federn und das Weiß des Schnees die Stille eines Wintermorgens.",
  "redoute-rose": "Eines der Blätter aus Redoutés „Les Roses“, nach dem Rosengarten der Kaiserin Joséphine gezeichnet. Von Hand vollendeter Punktierstich brachte die Durchsichtigkeit der Blütenblätter und jede Blattader zur Geltung, und die 168 Tafeln gelten bis heute als Gipfel der botanischen Kunst. Diese China-Rose war eine Stammform der europäischen remontierenden Rosen.",
  "haeckel-actiniae": "Eine der hundert Tafeln aus „Kunstformen der Natur“, 1904 vom Biologen Ernst Haeckel herausgegeben: Seeanemonen in allen Farben, symmetrisch angeordnet. Ein wissenschaftlicher Atlas, der sich wie Jugendstilornament liest und Architekten und Gestalter der Zeit anregte. Die sich wiederholenden Farben und Formen ergeben ein reizvolles Puzzle.",
  "blind-girl": "Nach einem Schauer steht ein doppelter Regenbogen über den Feldern, doch die blinde Straßenmusikantin, die ihr Akkordeon umklammert, kann ihn nicht sehen; nur ihre kleine Schwester dreht sich um und schaut. Das Mädchen erfährt die Welt über die Sonne auf ihrem Gesicht und den Grashalm in ihrer Hand. Millais verbindet feinste Landschaftsbeobachtung mit Mitgefühl auf dem Höhepunkt der präraffaelitischen Malerei.",
  "proserpine": "Proserpina, vom König der Unterwelt geraubt, hält den Granatapfel, in den sie gebissen hat: Weil sie davon aß, muss sie die Hälfte jedes Jahres unten verbringen. Modell war Jane Morris, die Frau eines Freundes, die Rossetti liebte, und er malte das Motiv achtmal. Der Efeu und der einfallende Lichtstrahl deuten die Oberwelt an, die sie nicht zurückgewinnen kann.",
  "straw-hat": "Vigée Le Brun, Bildnismalerin Marie Antoinettes, steht mit ihrer Palette im hellen Freilicht. Von einem Bildnis von Rubens angeregt, wählte sie Strohhut und natürliches Licht und stellt ihr Können als Malerin mit offenem Selbstbewusstsein aus. Die Eleganz der Pariser Gesellschaft vor der Revolution ist darin unversehrt bewahrt.",
  "blue-boy": "Ein Junge in blauem Satin des 17. Jahrhunderts steht stolz da und hält seinen Hut. Gainsborough brach absichtlich die Regel seiner Zeit, kaltes Blau dürfe ein Bild nie beherrschen, und erwies zugleich Van Dyck seine Reverenz. Als es 1921 nach Amerika verkauft wurde, standen neunzigtausend Menschen in London Schlange, um sich zu verabschieden.",
  "midsummer-dance": "In der Mittsommernacht in Dalarna in Schweden tanzen Dorfbewohner vor einem roten Häuschen bis zum Morgengrauen. In der nordischen weißen Nacht bleibt der Himmel um Mitternacht hell, und Zorn fing die Bewegung der Tanzenden in fließenden Strichen ein. Sein eigenes Lieblingswerk und das Hauptbild von Schwedens Nationalmaler.",
  "skagen-evening": "Zwei Frauen gehen Arm in Arm am Strand von Skagen, der Nordspitze Dänemarks: die Malerin Anna Ancher und Krøyers Frau Marie, ihre weißen Kleider vom blauen Abendlicht gefärbt. Es ist das klassische Bild der „blauen Stunde“, die die in Skagen versammelten skandinavischen Maler liebten, mit Himmel und Meer, die zu einer Farbe verschmelzen.",
  "hip-hip-hurrah": "Die in Skagen versammelten Maler und ihre Familien erheben an einem Gartentisch die Gläser. Durch das Laub strömendes Sonnenlicht bricht sich auf dem weißen Tuch und den Champagnergläsern, und rechts sitzt Anna Ancher mit ihrem Kind. Krøyer brauchte vier Jahre für dieses Gruppenbild der Künstlerkolonie von Skagen.",
  "hammershoi-interior": "In einem leeren Zimmer einer Kopenhagener Wohnung steht eine Frau in Schwarz mit dem Rücken zu uns. Es ist Ida, die Frau des Malers, und Hammershøi malt die Stille des Raums mit nichts als feinen Abstufungen von Grau und Weiß. Die ruhige Geometrie von Tür, Wand und Tisch wurde ein Jahrhundert später von Filmemachern und Gestaltern wiederentdeckt.",
  "pc-venice": "Eine Gondel gleitet in den 1890er Jahren den Canal Grande entlang. Ein Photochrom ist eine Schwarz-Weiß-Fotografie, die über lithografische Steine Schicht für Schicht koloriert wurde — vor der Farbfotografie das erste Medium, das den Menschen die berühmten Orte der Welt in Farbe zeigte. Die pastellfarbenen Palastfassaden und das grüne Wasser sind wie damals.",
  "pc-neuschwanstein": "Neuschwanstein, von Ludwig II. von Bayern als Traum vom mittelalterlichen Rittertum erbaut, in den 1890er Jahren fotografiert, als das Schloss noch keine zehn Jahre alt war. Es steht über den Wäldern am Fuß der Alpen, und die Türmchen, die später das Disney-Schloss anregten, sehen schon aus wie ein Märchen.",
  "pc-matterhorn": "Das Matterhorn von der Staffelalp oberhalb von Zermatt aus, im Abendlicht gerötet. Seit der Erstbesteigung von 1865 ist der Gipfel das Sinnbild des Alpentourismus, und das Photochrom zeigt ihn wie eine Ansichtskarte, rosa Himmel über grüner Weide.",
  "pc-hardanger": "Zwei Wasserfälle stürzen an einer Felswand des norwegischen Hardangerfjords herab. Ende des 19. Jahrhunderts waren die Fjorde ein neu in Mode gekommenes Ziel europäischer Reisender, und Bilder wie dieses nährten die Begeisterung. Das Hochformat vermittelt die volle Höhe der Wand.",
  "pc-sphinx": "Die Große Sphinx von Gizeh mit der Cheops-Pyramide dahinter, in einem Photochrom der 1890er Jahre. Die Sphinx steckt noch bis zu den Schultern im Sand, im Vordergrund liegen die freigelegten Steine eines Tempels, und Touristen auf Kamelen haben den Weg in die Wüste bereits gefunden.",
  "pc-bosphorus": "Der Bosporus von Kuleli am asiatischen Ufer Konstantinopels, des heutigen Istanbul. Hinter den Zypressen breiten sich Uferpaläste und das europäische Ufer unter einem rosa Abendhimmel aus — ein Blick auf die Meerenge in den letzten Jahren des Osmanischen Reichs.",
  "pc-niagara": "Die Amerikanischen Fälle und die Horseshoe Falls, um 1900 von der Stahlbogenbrücke über den Niagara aus gesehen. Die Detroit Publishing Company stellte Photochrome der Sehenswürdigkeiten Amerikas her, und die Fälle in ihrer Gischt gehörten zu den meistverkauften.",
  "pc-yosemite": "Half Dome, das Wahrzeichen des Yosemite Valley, ragt in einem Photochrom von 1898 zwischen Kiefern auf — acht Jahre, nachdem Yosemite Nationalpark geworden war. Der Kontrast von tiefgrünen Bäumen, grauem Granit und blassem Himmel zeigt den Reiz der von Hand aufgetragenen Farbe.",
  "pc-eiffel": "Der Trocadéro-Palast, während der Pariser Weltausstellung von 1900 durch den Sockel des Eiffelturms gesehen. Der Turm war für die Ausstellung gelb gestrichen worden, und das Photochrom bewahrt diese Farbe. Es zeigt ihn mit elf Jahren, als er noch als vorübergehender Bau galt.",
  "pc-tower-bridge": "Die 1894 vollendete Tower Bridge mit hochgeklappten Klappen, um ein Schiff durchzulassen. Dampfer und Segler auf der Themse und der Tower of London am anderen Ufer ergeben einen Blick aus den späten 1890er Jahren — ein Andenken an das neueste Wahrzeichen der Stadt.",
  "pc-rheinstein": "Burg Rheinstein auf einem Felsen über dem Rheintal. Ein preußischer Prinz baute die mittelalterliche Ruine im frühen 19. Jahrhundert romantisch wieder auf, und sie wurde zu einem Höhepunkt der Rheindampferfahrt. Unten liegen der gewundene Fluss und die Weinberge.",
  "pc-yellowstone": "Die „Farbtöpfe“ — Schlammquellen des Yellowstone-Nationalparks. Blubbernder Schlamm und Mineralablagerungen färben den Boden weiß und orange, als sei Farbe verschüttet worden, dahinter Kiefernwald. Detroit Publishing fotografierte sie 1902, um für den ersten Nationalpark der Welt zu werben.",
  "pc-colosseum": "Die Außenmauer des Kolosseums in den 1890er Jahren. Der heute von Touristen überfüllte Platz war damals eine stille Straße mit einer einzelnen Kutsche und ein paar Passanten. Der Gegensatz zwischen der eingestürzten und der erhaltenen Seite und das Abendlicht, das an den Bögen entlangläuft, machen die Größe des zweitausend Jahre alten Baus greifbar.",
  "pc-vesuvius": "Der rauchende Vesuv über der Bucht, von den Hügeln Neapels aus gesehen. In den 1890er Jahren dampfte der Vulkan unablässig, und dieser Anblick gehörte zu jedem Neapel-Besuch. Kiefern, die Stadt und die stille Bucht davor halten einen mittelmeerischen Nachmittag fest.",
  "pc-blue-grotto": "Ein kleines Boot treibt auf leuchtendem Wasser in der Blauen Grotte von Capri. Sonnenlicht, das durch eine Öffnung unter der Wasserlinie eindringt, erhellt das Wasser von unten; romantische Reisende des 19. Jahrhunderts entdeckten die Höhle wieder, und das Photochrom stellt von Hand ein Blau her, das die Fotografie allein nicht einfangen konnte.",
  "pc-lucerne": "Von den Felsen des Bürgenstocks südlich des Sees ein Blick über den Vierwaldstättersee, die Stadt und die fernen Alpen. In den 1890er Jahren war die Schweiz die Drehscheibe des europäischen Tourismus, und die Hotels am See verkauften Photochrom-Ansichtskarten, um Gäste anzulocken.",
  "pc-edinburgh": "Die Princes Street, Edinburghs Hauptstraße, mit ihren Gärten und dem Scott Monument und links der Burg auf ihrem Felsen. Eine Straßenszene der 1890er Jahre mit Pferdedroschken und Trams — heute so wenig verändert, dass der Vergleich das halbe Vergnügen ausmacht.",
  "pc-moscow": "Die goldkuppelige Christ-Erlöser-Kathedrale jenseits der Moskwa. 1883 zur Erinnerung an den Sieg über Napoleon vollendet, wurde sie 1931 von der sowjetischen Regierung gesprengt und in den 1990er Jahren wieder aufgebaut. Das Photochrom ist ein seltenes Zeugnis der ursprünglichen Kirche.",
  "pc-mont-saint-michel": "Die Felseninsel Mont-Saint-Michel vor der normannischen Küste mit der Abtei auf ihrem Gipfel. Der 1879 gebaute Damm führt im Vordergrund darauf zu, und der Sand der Ebbe umgibt die Insel. Der für Photochrome typische dramatische Himmel verstärkt die Stimmung des „Wunders des Abendlandes“.",
  "pc-amalfi": "Unter den Reben des alten Kapuzinerklosters auf seiner Klippe hindurch der Blick hinab auf die Amalfiküste. In den 1890er Jahren war aus dem Kloster ein Hotel geworden, in dem europäische Reisende abstiegen, und das blaue Meer und das Dorf zwischen den Terrassensäulen waren der Ausblick, den sie liebten.",
  "pc-chillon": "Das Schloss Chillon auf seinem Felsen am Rand des Genfersees, dahinter die verschneiten Gipfel der Dents du Midi. Durch Byrons „Der Gefangene von Chillon“ berühmt geworden, war das Schloss das ganze 19. Jahrhundert hindurch ein Wallfahrtsort für Reisende, und der blaue See und die weißen Berge werden im Photochrom lebendig.",
  "pc-interlaken": "Die Stadt Interlaken zwischen ihren beiden Seen, dahinter der ewige Schnee der Jungfrau. In den 1890er Jahren war Interlaken bereits ein Ausgangspunkt des Alpentourismus, und dieser Blick von den Hotelrasen war der Stolz der Stadt. Die Aare und grüne Wiesen im Vordergrund heben den Berg hervor.",
  "pc-mostar": "Die osmanische Steinbrücke aus dem 16. Jahrhundert über die Neretva in Mostar in Bosnien, in den 1890er Jahren unter österreichisch-ungarischer Herrschaft aufgenommen. Die Brücke wurde 1993 im Krieg zerstört und 2004 originalgetreu wieder errichtet. Steinhäuser, Fluss und der Bogen der Brücke fügen sich wie ein Gemälde.",
  "pc-ceylon": "Ein buddhistischer Tempel an der Straße von Colombo nach Galle auf Ceylon, dem heutigen Sri Lanka. Die weiße Stupa, Palmen und ein Ochsenkarren vermitteln den Alltag auf der Insel im Indischen Ozean in den 1890er Jahren. Die Firma Photoglob verkaufte eifrig auch exotische Ansichten von jenseits Europas.",
  "pc-madurai": "Der Torturm des Meenakshi-Tempels in Madurai in Südindien, vom Sockel bis zur Spitze mit Tausenden bemalter Skulpturen bedeckt, während sich unten am Tor Händler und Pilger versammeln. Die Handkolorierung des Photochroms hebt jede Figur hervor und macht es zu einem überwältigenden Puzzlemotiv.",
  "pc-golden-gate": "Brandung bricht sich an den Felsen beim Golden Gate in San Francisco, in einem Photochrom von 1901 — sechsunddreißig Jahre vor dem Bau der Brücke, als sich die Meerenge noch wild zum Pazifik öffnete. In der Ferne zieht ein Segler vorbei, und das Weiß der Gischt lebt durch die Handkolorierung.",
  "pc-banff": "Die Fälle des Bow River bei Banff in den kanadischen Rocky Mountains, dahinter ein Gipfel. Als in den 1880er Jahren die Canadian Pacific Railway eröffnete, wurde Banff der erste Nationalpark des Landes und ein Bergkurort, und dieses Photochrom von 1902 zeigte den Bahnreisenden, wie die Rockies aussehen.",
  "pc-havana": "Die Masten der Segelschiffe stehen 1904 wie ein Wald am Kai von San Francisco im Hafen von Havanna, auf der Mole stapeln sich Fässer und Kisten. Ein Zeugnis amerikanischer Fotografen, die kurz nach der Unabhängigkeit von Spanien nach Kuba kamen — voller Betrieb eines karibischen Hafens.",
  "pc-brussels": "Die reich geschmückten Fassaden der Zunfthäuser des 17. Jahrhunderts rund um die Grand-Place in Brüssel, jedes Stockwerk mit Vergoldung und Skulptur beladen und jedes Haus noch mit dem Namen einer alten Kaufmannszunft, dazu ein Blumenmarkt auf dem Platz. Einer der schönsten Plätze Europas, wie er in den 1890er Jahren aussah.",
  "pc-prague": "Der Platz vor dem Haupttor der Prager Burg. Ein Soldat der österreichisch-ungarischen Zeit hält am Tor Wache, und eine einzelne Kutsche quert den Platz. Der heute von Touristen überlaufene Ort ist leer, nur die cremefarbenen Burgmauern fangen die Sonne — das macht den Lauf der Zeit anschaulich.",
  "pc-innsbruck": "Das „Goldene Dachl“ in der Altstadt von Innsbruck, ein 1500 für Kaiser Maximilian erbauter Erker, von dem aus er die Ereignisse auf dem Platz verfolgen konnte, sein Dach mit 2.657 vergoldeten Kupferschindeln gedeckt. Die Fresken an der Wand und die geschnitzte Brüstung werden in den Farben des Photochroms lebendig.",
  "pc-milan": "Der Mailänder Dom und der Platz davor, links der Eingang zur Galleria. Kutschen und Passanten queren den Platz der 1890er Jahre rund um das Reiterstandbild Viktor Emanuels II. Die von Marmorfialen starrende Domfassade ist der schwerste und lohnendste Teil des Puzzles.",
  "pc-pisa": "Der Schiefe Turm von Pisa in den 1890er Jahren, schon geneigt, aber anders als heute nur von niedrigen Häusern und freiem Gelände umgeben. Es ist der Turm, bevor die Ingenieursarbeiten des späten 20. Jahrhunderts ihn ein Stück zurückzogen — weißer Marmor allein unter blassem Himmel.",
  "pc-giralda": "La Giralda, der Glockenturm der Kathedrale von Sevilla: ein Renaissance-Glockenstuhl des 16. Jahrhunderts, auf das Minarett einer maurischen Moschee des 12. Jahrhunderts gesetzt, sodass islamische und christliche Architektur in einem Turm übereinanderstehen. Aus einer engen Gasse der 1890er Jahre gesehen, leuchtet er in rosa Backstein.",
  "pc-alhambra": "Ein Säulengang im Inneren der Alhambra in Granada, mit dem zarten Stuckwerk des maurischen Palasts und dem Blick durch die Bögen auf Gärten und Hügel. Nach Washington Irvings Buch strömten im 19. Jahrhundert die Reisenden hierher, und das Photochrom gibt es in rötlichen Mauern und grünem Garten wieder.",
  "pc-loch-katrine": "Ein Dampfboot am Steg von Loch Katrine in den Trossachs in Schottland. Als Schauplatz von Walter Scotts „Das Fräulein vom See“ berühmt geworden, zog der See das ganze 19. Jahrhundert hindurch Besucher an, und der 1900 vom Stapel gelaufene Dampfer „Sir Walter Scott“ verkehrt dort bis heute.",
  "pc-summer-palace": "Das Marmorboot auf dem Kunming-See im Sommerpalast von Peking, ein bootsförmiger Pavillon, der erneuert wurde, als Kaiserinwitwe Cixi Marinegelder in den Wiederaufbau des Palasts umleitete. Das Photochrom der 1890er Jahre zeigt ihn, während die Qing-Dynastie noch herrschte — weißer Marmor und bemalte Geländer im See gespiegelt.",
  "sp-pillars": "Türme aus Gas und Staub im Herzen des Adlernebels, wo neue Sterne entstehen. Hubble machte die Szene 1995 berühmt; 2022 fotografierte das James-Webb-Weltraumteleskop sie im nahen Infrarot erneut und enthüllte hinter dem Staub neugeborene rote Sterne. Die Säulen sind rund vier bis fünf Lichtjahre hoch.",
  "sp-cosmic-cliffs": "Eines der ersten Bilder, die das James-Webb-Weltraumteleskop im Juli 2022 veröffentlichte: eine Sternentstehungsregion am Rand des Carinanebels. Was wie ein mondbeschienenes Gebirge aussieht, ist der Saum einer riesigen Gaswolke, die vom Ultraviolettlicht und den Winden neugeborener Sterne abgetragen wird; die höchsten Gipfel messen etwa sieben Lichtjahre.",
  "sp-crab": "Im Jahr 1054 hielten chinesische und arabische Astronomen fest, wie ein Stern so hell explodierte, dass er am Tag zu sehen war; der Krebsnebel ist das Wrack jener Supernova. In diesem Hubble-Mosaik aus vierundzwanzig Aufnahmen sind die orangefarbenen Fäden die zerfetzten Reste des Sterns, und das blaue Leuchten in der Mitte stammt von einem Neutronenstern, der sich dreißigmal pro Sekunde dreht.",
  "sp-helix": "Ein planetarischer Nebel etwa 650 Lichtjahre entfernt im Wassermann: ein sonnenähnlicher Stern am Ende seines Lebens, der seine äußeren Schichten ins All bläst. Seine Ähnlichkeit mit einem riesigen Auge brachte ihm den Beinamen „Auge Gottes“ ein. Das Bild vereint Hubble- und erdgebundene Daten; der innere Ring misst etwa zwei Lichtjahre.",
  "sp-whirlpool": "Eine Spiralgalaxie rund dreißig Millionen Lichtjahre entfernt in den Jagdhunden, deren Arme so klar gezeichnet sind, dass sie als „Strudelgalaxie“ im Lehrbuch steht. Die kleine gelbe Galaxie rechts zieht vorbei und rührt mit ihrer Schwerkraft die Arme auf, sodass entlang ihnen kettenweise neue Sterne entstehen; die roten Flecken sind Wasserstoffwolken, in denen Sterne geboren werden.",
  "sp-sombrero": "Eine Galaxie etwa achtundzwanzig Millionen Lichtjahre entfernt in der Jungfrau, fast von der Kante gesehen. Ihre helle Verdickung und das dunkle Staubband, das sie umgürtet, erinnern an einen mexikanischen Sombrero. Hubble fügte für diese Ansicht sechs Aufnahmen zusammen; die Galaxie misst rund fünfzigtausend Lichtjahre und birgt in ihrem Zentrum ein Schwarzes Loch von einer Milliarde Sonnenmassen.",
  "sp-orion": "Die Sternentstehungswolke, die unter dem Gürtel des Orion gerade mit bloßem Auge zu sehen ist — die nächstgelegene große Sternenwiege der Erde. Hubbles Mosaik aus 520 Aufnahmen enthält über dreitausend neugeborene Sterne und Scheiben, in denen Planeten entstehen. Die vier hellen Sterne in der Mitte sind das Trapez.",
  "sp-earthrise": "Am Heiligabend 1968 fotografierte der Astronaut William Anders an Bord von Apollo 8 im Mondorbit die über dem Mondhorizont aufgehende Erde. Zum ersten Mal sahen Menschen ihren ganzen Planeten von außen, und das Bild gilt als die Fotografie, die die Umweltbewegung auslöste. Im Hochformat aufgenommen, wird es meist so gedreht gezeigt.",
};
